constexpr uint64_t FnvOffsetBasis = 1469598103934665603ull;
constexpr uint64_t FnvPrime = 1099511628211ull;
constexpr uint32_t SolMetalSupportedFPFastMathModes =
    static_cast<uint32_t>(spv::FPFastMathModeNotNaNMask) |
    static_cast<uint32_t>(spv::FPFastMathModeNotInfMask) |
    static_cast<uint32_t>(spv::FPFastMathModeNSZMask) |
    static_cast<uint32_t>(spv::FPFastMathModeAllowRecipMask) |
    static_cast<uint32_t>(spv::FPFastMathModeAllowReassocMask) |
    static_cast<uint32_t>(spv::FPFastMathModeAllowContractMask);

static_assert(
    sizeof(MTLDrawPrimitivesIndirectArguments) == 4 * sizeof(uint32_t));
static_assert(
    offsetof(MTLDrawPrimitivesIndirectArguments, baseInstance) ==
        3 * sizeof(uint32_t));
static_assert(
    sizeof(MTLDrawIndexedPrimitivesIndirectArguments) ==
        5 * sizeof(uint32_t));
static_assert(
    offsetof(MTLDrawIndexedPrimitivesIndirectArguments, baseVertex) ==
        3 * sizeof(uint32_t));
static_assert(sizeof(SolMetalPresentTextureDescriptor) == 64);
static_assert(offsetof(SolMetalPresentTextureDescriptor, source_left) == 28);
static_assert(offsetof(SolMetalPresentTextureDescriptor, flags) == 52);

typedef NS_ENUM(uint8_t, SolMetalMathPolicy) {
    SolMetalMathPolicySafe = 0,
    SolMetalMathPolicyRelaxed = 1,
    SolMetalMathPolicyFast = 2,
};

class SolMetalCompilerMSL final : public spirv_cross::CompilerMSL {
public:
    using spirv_cross::CompilerMSL::CompilerMSL;

    bool selectedEntryPointMayTerminateInvocation() {
        class TerminationHandler final : public OpcodeHandler {
        public:
            explicit TerminationHandler(spirv_cross::Compiler &compiler)
                : OpcodeHandler(compiler) {}

            bool handle(
                spv::Op opcode,
                const uint32_t *,
                uint32_t) override {
                if (opcode == spv::OpKill ||
                    opcode == spv::OpTerminateInvocation ||
                    opcode == spv::OpDemoteToHelperInvocation) {
                    mayTerminate = true;
                    return false;
                }
                return true;
            }

            bool handle_terminator(
                const spirv_cross::SPIRBlock &block) override {
                if (block.terminator ==
                    spirv_cross::SPIRBlock::Kill) {
                    mayTerminate = true;
                    return false;
                }
                return true;
            }

            bool mayTerminate = false;
        };

        TerminationHandler handler(*this);
        const spirv_cross::SPIREntryPoint &entry = get_entry_point();
        traverse_all_reachable_opcodes(
            get<spirv_cross::SPIRFunction>(entry.self),
            handler);
        return handler.mayTerminate;
    }
};

static SolMetalMathPolicy MathPolicyForSPIRVFlags(uint32_t flags) {
    constexpr uint32_t relaxedFlags =
        static_cast<uint32_t>(spv::FPFastMathModeNSZMask) |
        static_cast<uint32_t>(spv::FPFastMathModeAllowRecipMask) |
        static_cast<uint32_t>(spv::FPFastMathModeAllowReassocMask) |
        static_cast<uint32_t>(spv::FPFastMathModeAllowContractMask);
    if ((flags & relaxedFlags) != relaxedFlags) {
        return SolMetalMathPolicySafe;
    }
    constexpr uint32_t finiteFlags =
        static_cast<uint32_t>(spv::FPFastMathModeNotNaNMask) |
        static_cast<uint32_t>(spv::FPFastMathModeNotInfMask);
    return (flags & finiteFlags) == finiteFlags
        ? SolMetalMathPolicyFast
        : SolMetalMathPolicyRelaxed;
}

static uint64_t HashBytes(const void *bytes, size_t length, uint64_t seed) {
    const auto *cursor = static_cast<const uint8_t *>(bytes);
    uint64_t hash = seed;
    for (size_t index = 0; index < length; ++index) {
        hash ^= cursor[index];
        hash *= FnvPrime;
    }
    return hash;
}

static bool EnvironmentFlagEnabled(const char *name) {
    const char *value = std::getenv(name);
    return value != nullptr && std::strcmp(value, "1") == 0;
}

static uint64_t EnvironmentUInt64(
    const char *name,
    uint64_t fallback,
    uint64_t maximum) {
    const char *value = std::getenv(name);
    if (value == nullptr || value[0] == '\0') {
        return fallback;
    }
    errno = 0;
    char *end = nullptr;
    const unsigned long long parsed = std::strtoull(value, &end, 10);
    if (errno != 0 || end == value || *end != '\0' || parsed == 0) {
        return fallback;
    }
    return std::min<uint64_t>(parsed, maximum);
}

static bool UseD32BackingForD16() {
    return EnvironmentFlagEnabled("SOL_METAL_D16_BACKING_D32");
}

static double QuantizeD16Depth(double value) {
    constexpr double D16Maximum = 65'535.0;
    const double bounded = std::clamp(value, 0.0, 1.0);
    return std::nearbyint(bounded * D16Maximum) / D16Maximum;
}

static void CopyText(char *destination, size_t capacity, NSString *value) {
    if (destination == nullptr || capacity == 0) {
        return;
    }

    destination[0] = '\0';
    if (value == nil) {
        return;
    }

    const char *utf8 = value.UTF8String;
    if (utf8 != nullptr) {
        std::strncpy(destination, utf8, capacity - 1);
        destination[capacity - 1] = '\0';
    }
}

static void CopyText(
    char *destination,
    size_t capacity,
    const std::string &value) {
    if (destination == nullptr || capacity == 0) {
        return;
    }
    const size_t copyLength = std::min(value.size(), capacity - 1);
    std::memcpy(destination, value.data(), copyLength);
    destination[copyLength] = '\0';
}

static void SetTranslationError(
    SolMetalSpirvTranslationReport *report,
    NSString *message) {
    if (report != nullptr) {
        CopyText(report->last_error, sizeof(report->last_error), message);
    }
}

static void SetReportError(
    SolMetalValidationReport *report,
    SolMetalStatus status,
    NSString *message) {
    if (report == nullptr) {
        return;
    }
    report->last_status = status;
    CopyText(report->last_error, sizeof(report->last_error), message);
}

static SolMetalStatus ValidateCapabilitiesStruct(
    SolMetalCapabilities *capabilities) {
    if (capabilities == nullptr) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }
    if (capabilities->struct_size < sizeof(SolMetalCapabilities)) {
        return SOL_METAL_STATUS_INCOMPATIBLE_ABI;
    }
    return SOL_METAL_STATUS_OK;
}

static SolMetalStatus ValidateReportStruct(
    SolMetalValidationReport *report) {
    if (report == nullptr) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }
    if (report->struct_size < sizeof(SolMetalValidationReport)) {
        return SOL_METAL_STATUS_INCOMPATIBLE_ABI;
    }
    return SOL_METAL_STATUS_OK;
}

static uint32_t HighestAppleGPUFamily(id<MTLDevice> device) {
    if (device == nil) {
        return 0;
    }

    if (@available(macOS 26.0, *)) {
        if ([device supportsFamily:MTLGPUFamilyApple10]) {
            return 10;
        }
    }
    if (@available(macOS 15.0, *)) {
        if ([device supportsFamily:MTLGPUFamilyApple9]) {
            return 9;
        }
    }
    if (@available(macOS 13.0, *)) {
        if ([device supportsFamily:MTLGPUFamilyApple8]) {
            return 8;
        }
    }
    if (@available(macOS 11.0, *)) {
        if ([device supportsFamily:MTLGPUFamilyApple7]) {
            return 7;
        }
    }
    if ([device supportsFamily:MTLGPUFamilyApple6]) {
        return 6;
    }
    if ([device supportsFamily:MTLGPUFamilyApple5]) {
        return 5;
    }
    if ([device supportsFamily:MTLGPUFamilyApple4]) {
        return 4;
    }
    if ([device supportsFamily:MTLGPUFamilyApple3]) {
        return 3;
    }
    if ([device supportsFamily:MTLGPUFamilyApple2]) {
        return 2;
    }
    if ([device supportsFamily:MTLGPUFamilyApple1]) {
        return 1;
    }
    return 0;
}

#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Wdeprecated-declarations"
static bool SupportsLayeredVertexOutput(id<MTLDevice> device) {
    if (device == nil) {
        return false;
    }
    // [[render_target_array_index]] from the vertex stage is supported by the
    // Apple5 family and by the discrete/integrated Mac GPU families. Keep this
    // explicit so older Apple GPUs never receive the GAL capability.
    return [device supportsFamily:MTLGPUFamilyApple5] ||
        [device supportsFamily:MTLGPUFamilyMac1] ||
        [device supportsFamily:MTLGPUFamilyMac2];
}
#pragma clang diagnostic pop

static SolMetalStatus FillCapabilities(
    id<MTLDevice> device,
    SolMetalCapabilities *capabilities) {
    const SolMetalStatus validation = ValidateCapabilitiesStruct(capabilities);
    if (validation != SOL_METAL_STATUS_OK) {
        return validation;
    }
    if (device == nil) {
        return SOL_METAL_STATUS_NO_DEVICE;
    }

    std::memset(capabilities, 0, sizeof(*capabilities));
    capabilities->struct_size = sizeof(*capabilities);
    capabilities->abi_version = SOL_METAL_ABI_VERSION;
    capabilities->registry_id = device.registryID;
    capabilities->max_buffer_length = device.maxBufferLength;
    capabilities->recommended_max_working_set_size =
        device.recommendedMaxWorkingSetSize;

    const MTLSize maxThreads = device.maxThreadsPerThreadgroup;
    const uint64_t threadCount =
        static_cast<uint64_t>(maxThreads.width) *
        static_cast<uint64_t>(maxThreads.height) *
        static_cast<uint64_t>(maxThreads.depth);
    capabilities->max_threads_per_threadgroup = static_cast<uint32_t>(
        std::min<uint64_t>(threadCount, std::numeric_limits<uint32_t>::max()));
    capabilities->apple_gpu_family = HighestAppleGPUFamily(device);
    capabilities->argument_buffer_tier =
        device.argumentBuffersSupport == MTLArgumentBuffersTier2 ? 2 : 1;
    capabilities->has_unified_memory = device.hasUnifiedMemory ? 1 : 0;
    capabilities->is_low_power = device.lowPower ? 1 : 0;
    capabilities->is_removable = device.removable ? 1 : 0;
    capabilities->is_headless = device.headless ? 1 : 0;
    capabilities->supports_bc_texture_compression =
        device.supportsBCTextureCompression ? 1 : 0;
    capabilities->supports_ray_tracing = device.supportsRaytracing ? 1 : 0;
    capabilities->supports_binary_archives =
        [device respondsToSelector:
            @selector(newBinaryArchiveWithDescriptor:error:)] ? 1 : 0;
    capabilities->supports_layered_vertex_output =
        SupportsLayeredVertexOutput(device) ? 1 : 0;
    CopyText(capabilities->device_name, sizeof(capabilities->device_name), device.name);
    return SOL_METAL_STATUS_OK;
}

