};

struct SolMetalRuntimeDrawPassKey {
    uintptr_t colorTextures[SOL_METAL_MAX_COLOR_ATTACHMENTS];
    uintptr_t depthStencilTexture;
    uint64_t renderTargetWidth;
    uint64_t renderTargetHeight;
    uint64_t hasStencil;
    uint64_t renderTargetArrayLength;
};

static bool RuntimeDrawPassKeysEqual(
    const SolMetalRuntimeDrawPassKey &left,
    const SolMetalRuntimeDrawPassKey &right) {
    for (uint32_t index = 0;
         index < SOL_METAL_MAX_COLOR_ATTACHMENTS;
         ++index) {
        if (left.colorTextures[index] != right.colorTextures[index]) {
            return false;
        }
    }
    return left.depthStencilTexture == right.depthStencilTexture &&
        left.renderTargetWidth == right.renderTargetWidth &&
        left.renderTargetHeight == right.renderTargetHeight &&
        left.hasStencil == right.hasStencil &&
        left.renderTargetArrayLength == right.renderTargetArrayLength;
}

