@implementation SolMetalContextObject

- (nullable instancetype)initWithDevice:(id<MTLDevice>)device {
    self = [super init];
    if (self == nil || device == nil) {
        return nil;
    }

    _device = device;
    _commandQueue = [device newCommandQueue];
    _validationLock = [[NSLock alloc] init];
    _timelineCondition = [[NSCondition alloc] init];
    _runtimeSubmissionCondition = [[NSCondition alloc] init];
    _runtimeBatchLock = [[NSRecursiveLock alloc] init];
    _shaderLibraryCache = [[NSCache alloc] init];
    NSMutableArray<NSLock *> *shaderLibraryCacheLocks =
        [NSMutableArray arrayWithCapacity:64];
    for (NSUInteger index = 0; index < 64; ++index) {
        [shaderLibraryCacheLocks addObject:[[NSLock alloc] init]];
    }
    _shaderLibraryCacheLocks = [shaderLibraryCacheLocks copy];
    _colorBlitPipelineCache = [[NSCache alloc] init];
    _textureClearPipelineCache = [[NSCache alloc] init];
    _depthStencilClearPipelineCache = [[NSCache alloc] init];
    if (_commandQueue == nil || _validationLock == nil ||
        _timelineCondition == nil || _runtimeSubmissionCondition == nil ||
        _runtimeBatchLock == nil ||
        _shaderLibraryCache == nil || _shaderLibraryCacheLocks.count != 64 ||
        _colorBlitPipelineCache == nil ||
        _textureClearPipelineCache == nil ||
        _depthStencilClearPipelineCache == nil) {
        return nil;
    }
    _timelineSubmittedValue = 0;
    _timelineCompletedValue = 0;
    _timelineFirstFailedValue = 0;
    _timelineLastStatus = SOL_METAL_STATUS_OK;
    _runtimeCommandStatus = SOL_METAL_STATUS_OK;
    _runtimeSubmissionsInFlight = 0;
    _runtimeDrawCommandBuffer = nil;
    _runtimeDrawEncoder = nil;
    _runtimeDrawPassKeyValid = NO;
    _runtimeDrawPassKey = {};
    _runtimeDrawCount = 0;
    _runtimeBatchedDrawCount = 0;
    _runtimeDrawCommandBufferCount = 0;
    _runtimeDrawBoundaryFlushCount = 0;
    _runtimeDrawRenderPassCount = 0;
    _runtimeMaximumDrawBatchSize = 0;
    _runtimeRenderPassCoalescingEnabled =
        !EnvironmentFlagEnabled(
            "SOL_METAL_DEBUG_DISABLE_RENDER_PASS_COALESCING");
    _runtimeDirectMutationBatchingEnabled = EnvironmentFlagEnabled(
        "SOL_METAL_DIRECT_MUTATION_BATCHING");
    _runtimeMutationEncoderLimit = static_cast<NSUInteger>(EnvironmentUInt64(
        "SOL_METAL_DIRECT_MUTATION_MAX_ENCODERS",
        12,
        64));
    _runtimeMutationTransientByteLimit = EnvironmentUInt64(
        "SOL_METAL_DIRECT_MUTATION_MAX_TRANSIENT_BYTES",
        32ull * 1024ull * 1024ull,
        512ull * 1024ull * 1024ull);
    _runtimePendingMutationCount = 0;
    _runtimePendingMutationEncoderCount = 0;
    _runtimePendingMutationTransientBytes = 0;
    _runtimeBorrowedMutationCount = 0;
    _runtimeBorrowedMutationEncoderCount = 0;
    _runtimeBorrowedMutationTransientBytes = 0;
    _runtimeStandaloneMutationCount = 0;
    _runtimeDiscardedPendingCommandBufferCount = 0;
    _runtimeDiscardedPendingDrawCount = 0;
    _runtimeMaximumMutationCount = 0;
    _runtimeMaximumMutationEncoderCount = 0;
    _runtimeMaximumMutationTransientBytes = 0;
    std::memset(
        _runtimeBatchFlushReasonCounts,
        0,
        sizeof(_runtimeBatchFlushReasonCounts));
    _lastError = @"";
    _commandQueue.label = @"SolMetal Primary Queue";
    _shaderLibraryCache.name = @"SolMetal MSL Library Cache";
    _shaderLibraryCache.countLimit = 2'048;
    _shaderLibraryCache.totalCostLimit = 64 * 1024 * 1024;
    _colorBlitPipelineCache.name = @"SolMetal Color Blit Pipeline Cache";
    _colorBlitPipelineCache.countLimit = 64;
    _textureClearPipelineCache.name = @"SolMetal Texture Clear Pipeline Cache";
    _textureClearPipelineCache.countLimit = 256;
    _depthStencilClearPipelineCache.name =
        @"SolMetal Depth Stencil Clear Pipeline Cache";
    _depthStencilClearPipelineCache.countLimit = 32;
    return self;
}

- (void)setLastErrorMessage:(NSString *)message {
    @synchronized (self) {
        _lastError = [message copy] ?: @"";
    }
}

- (void)copyLastErrorTo:(char *)destination capacity:(size_t)capacity {
    @synchronized (self) {
        CopyText(destination, capacity, _lastError ?: @"");
    }
}

- (void)recordRuntimeCommandFailure:(NSString *)message {
    @synchronized (self) {
        if (_runtimeCommandStatus == SOL_METAL_STATUS_OK) {
            _runtimeCommandStatus = SOL_METAL_STATUS_COMMAND_FAILED;
            _lastError = [message copy] ?: @"Metal command execution failed";
        }
    }
}

- (SolMetalStatus)beginRuntimeCommand {
    @synchronized (self) {
        if (_runtimeCommandStatus == SOL_METAL_STATUS_OK) {
            _lastError = @"";
        }
        return _runtimeCommandStatus;
    }
}

- (SolMetalStatus)beginRuntimeSubmission {
    // Overlap guest command preparation with Metal while bounding transient
    // upload/copy storage. FIFO command-queue ordering remains unchanged.
    constexpr NSUInteger MaximumRuntimeSubmissionsInFlight = 16;
    [_runtimeSubmissionCondition lock];
    while (_runtimeSubmissionsInFlight >=
           MaximumRuntimeSubmissionsInFlight) {
        [_runtimeSubmissionCondition wait];
    }
    _runtimeSubmissionsInFlight += 1;
    [_runtimeSubmissionCondition unlock];

    const SolMetalStatus status = [self beginRuntimeCommand];
    if (status != SOL_METAL_STATUS_OK) {
        [self endRuntimeSubmission];
    }
    return status;
}

- (void)endRuntimeSubmission {
    [_runtimeSubmissionCondition lock];
    if (_runtimeSubmissionsInFlight > 0) {
        _runtimeSubmissionsInFlight -= 1;
    }
    [_runtimeSubmissionCondition signal];
    [_runtimeSubmissionCondition unlock];
}

- (SolMetalStatus)runtimeCommandFailureStatus {
    @synchronized (self) {
        return _runtimeCommandStatus;
    }
}

- (nullable id<MTLLibrary>)libraryWithSource:(NSString *)source
                            fpFastMathFlags:(uint32_t)fpFastMathFlags
                          preserveInvariance:(BOOL)preserveInvariance
                                    cacheHit:(BOOL *)cacheHit
                                       error:(NSError **)error {
    if (cacheHit != nullptr) {
        *cacheHit = NO;
    }
    if (source.length == 0) {
        if (error != nullptr) {
            *error = [NSError
                errorWithDomain:@"com.solemu.SolMetal"
                code:SOL_METAL_STATUS_INVALID_ARGUMENT
                userInfo:@{NSLocalizedDescriptionKey: @"Metal shader source was empty"}];
        }
        return nil;
    }

    NSData *sourceData = [source dataUsingEncoding:NSUTF8StringEncoding];
    if (sourceData == nil) {
        return nil;
    }
    const SolMetalMathPolicy mathPolicy =
        MathPolicyForSPIRVFlags(fpFastMathFlags);
    NSMutableData *key = [NSMutableData dataWithCapacity:sourceData.length + 2];
    const uint8_t invarianceKey = preserveInvariance ? 1u : 0u;
    [key appendBytes:&invarianceKey length:sizeof(invarianceKey)];
    [key appendBytes:&mathPolicy length:sizeof(mathPolicy)];
    [key appendData:sourceData];

    // NSCache makes individual accesses safe, but a lookup followed by a
    // compile and insert is not atomic. Serialize identical shader/options
    // keys while retaining parallel compilation across 64 independent lanes.
    NSLock *cacheLock =
        _shaderLibraryCacheLocks[key.hash % _shaderLibraryCacheLocks.count];
    [cacheLock lock];
    id<MTLLibrary> cached = [_shaderLibraryCache objectForKey:key];
    if (cached != nil) {
        if (cacheHit != nullptr) {
            *cacheHit = YES;
        }
        [cacheLock unlock];
        return cached;
    }

    MTLCompileOptions *options = [[MTLCompileOptions alloc] init];
    switch (mathPolicy) {
        case SolMetalMathPolicySafe:
            options.mathMode = MTLMathModeSafe;
            options.mathFloatingPointFunctions =
                MTLMathFloatingPointFunctionsPrecise;
            break;
        case SolMetalMathPolicyRelaxed:
            options.mathMode = MTLMathModeRelaxed;
            options.mathFloatingPointFunctions =
                MTLMathFloatingPointFunctionsPrecise;
            break;
        case SolMetalMathPolicyFast:
            options.mathMode = MTLMathModeFast;
            options.mathFloatingPointFunctions =
                MTLMathFloatingPointFunctionsFast;
            break;
    }
    options.preserveInvariance = preserveInvariance;
    id<MTLLibrary> library = [_device
        newLibraryWithSource:source
        options:options
        error:error];
    if (library != nil) {
        [_shaderLibraryCache setObject:library forKey:key cost:key.length];
    }
    [cacheLock unlock];
    return library;
}

- (nullable id<MTLLibrary>)libraryWithSource:(NSString *)source
                          preserveInvariance:(BOOL)preserveInvariance
                                    cacheHit:(BOOL *)cacheHit
                                       error:(NSError **)error {
    return [self
        libraryWithSource:source
        fpFastMathFlags:SolMetalSupportedFPFastMathModes
        preserveInvariance:preserveInvariance
        cacheHit:cacheHit
        error:error];
}

- (nullable id<MTLLibrary>)libraryWithSource:(NSString *)source
                                    cacheHit:(BOOL *)cacheHit
                                       error:(NSError **)error {
    return [self
        libraryWithSource:source
        preserveInvariance:NO
        cacheHit:cacheHit
        error:error];
}

- (BOOL)preparePresentationResources:(NSError **)error {
    if (_presentationPipeline != nil &&
        _presentationNearestSampler != nil &&
        _presentationLinearSampler != nil) {
        return YES;
    }

    static NSString *const source = @R"(
#include <metal_stdlib>
using namespace metal;

struct SolPresentVertex {
    float4 position [[position]];
    float2 textureCoordinate;
};

vertex SolPresentVertex sol_present_vertex(uint vertexID [[vertex_id]]) {
    const float2 positions[3] = {
        float2(-1.0, -1.0),
        float2( 3.0, -1.0),
        float2(-1.0,  3.0),
    };
    const float2 textureCoordinates[3] = {
        float2(0.0,  1.0),
        float2(2.0,  1.0),
        float2(0.0, -1.0),
    };
    SolPresentVertex output;
    output.position = float4(positions[vertexID], 0.0, 1.0);
    output.textureCoordinate = textureCoordinates[vertexID];
    return output;
}

fragment float4 sol_present_fragment(
    SolPresentVertex input [[stage_in]],
    texture2d<float> sourceTexture [[texture(0)]],
    sampler sourceSampler [[sampler(0)]],
    constant float4 &sourceRegion [[buffer(0)]],
    constant uint2 &flipAxes [[buffer(1)]]) {
    float2 coordinate = input.textureCoordinate;
    if (flipAxes.x != 0) {
        coordinate.x = 1.0 - coordinate.x;
    }
    if (flipAxes.y != 0) {
        coordinate.y = 1.0 - coordinate.y;
    }
    coordinate = sourceRegion.xy + coordinate * sourceRegion.zw;
    return sourceTexture.sample(sourceSampler, coordinate);
}
)";

    BOOL cacheHit = NO;
    id<MTLLibrary> library = [self
        libraryWithSource:source
        cacheHit:&cacheHit
        error:error];
    if (library == nil) {
        return NO;
    }
    id<MTLFunction> vertexFunction = [library
        newFunctionWithName:@"sol_present_vertex"];
    id<MTLFunction> fragmentFunction = [library
        newFunctionWithName:@"sol_present_fragment"];
    if (vertexFunction == nil || fragmentFunction == nil) {
        if (error != nullptr) {
            *error = [NSError
                errorWithDomain:@"com.solemu.SolMetal"
                code:SOL_METAL_STATUS_SHADER_COMPILATION_FAILED
                userInfo:@{NSLocalizedDescriptionKey:
                    @"SolMetal presentation shader functions were unavailable"}];
        }
        return NO;
    }

    MTLRenderPipelineDescriptor *pipelineDescriptor =
        [[MTLRenderPipelineDescriptor alloc] init];
    pipelineDescriptor.label = @"SolMetal Texture Presentation Pipeline";
    pipelineDescriptor.vertexFunction = vertexFunction;
    pipelineDescriptor.fragmentFunction = fragmentFunction;
    pipelineDescriptor.colorAttachments[0].pixelFormat =
        MTLPixelFormatBGRA8Unorm;
    id<MTLRenderPipelineState> pipeline = [_device
        newRenderPipelineStateWithDescriptor:pipelineDescriptor
        error:error];
    if (pipeline == nil) {
        return NO;
    }

    MTLSamplerDescriptor *nearestDescriptor =
        [[MTLSamplerDescriptor alloc] init];
    nearestDescriptor.label = @"SolMetal Nearest Presentation Sampler";
    nearestDescriptor.minFilter = MTLSamplerMinMagFilterNearest;
    nearestDescriptor.magFilter = MTLSamplerMinMagFilterNearest;
    nearestDescriptor.mipFilter = MTLSamplerMipFilterNotMipmapped;
    nearestDescriptor.sAddressMode = MTLSamplerAddressModeClampToEdge;
    nearestDescriptor.tAddressMode = MTLSamplerAddressModeClampToEdge;

    MTLSamplerDescriptor *linearDescriptor =
        [nearestDescriptor copy];
    linearDescriptor.label = @"SolMetal Linear Presentation Sampler";
    linearDescriptor.minFilter = MTLSamplerMinMagFilterLinear;
    linearDescriptor.magFilter = MTLSamplerMinMagFilterLinear;

    id<MTLSamplerState> nearestSampler = [_device
        newSamplerStateWithDescriptor:nearestDescriptor];
    id<MTLSamplerState> linearSampler = [_device
        newSamplerStateWithDescriptor:linearDescriptor];
    if (nearestSampler == nil || linearSampler == nil) {
        if (error != nullptr) {
            *error = [NSError
                errorWithDomain:@"com.solemu.SolMetal"
                code:SOL_METAL_STATUS_ALLOCATION_FAILED
                userInfo:@{NSLocalizedDescriptionKey:
                    @"SolMetal presentation samplers were unavailable"}];
        }
        return NO;
    }

    _presentationPipeline = pipeline;
    _presentationNearestSampler = nearestSampler;
    _presentationLinearSampler = linearSampler;
    return YES;
}

- (SolMetalStatus)encodePresentationTexture:(id<MTLTexture>)sourceTexture
                         destinationTexture:(id<MTLTexture>)destinationTexture
                              commandBuffer:(id<MTLCommandBuffer>)commandBuffer
                                  descriptor:(const SolMetalPresentTextureDescriptor &)descriptor
                                  loadAction:(MTLLoadAction)loadAction {
    if (sourceTexture == nil || destinationTexture == nil ||
        commandBuffer == nil || _presentationPipeline == nil ||
        (descriptor.filter != SOL_METAL_SAMPLER_FILTER_NEAREST &&
         descriptor.filter != SOL_METAL_SAMPLER_FILTER_LINEAR) ||
        (descriptor.flags & ~(SOL_METAL_PRESENT_FLIP_X |
                              SOL_METAL_PRESENT_FLIP_Y)) != 0) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }

    const bool fullSourceX = descriptor.source_left == 0 &&
        descriptor.source_right == 0;
    const bool fullSourceY = descriptor.source_top == 0 &&
        descriptor.source_bottom == 0;
    const int64_t sourceLeft = fullSourceX ? 0 : descriptor.source_left;
    const int64_t sourceTop = fullSourceY ? 0 : descriptor.source_top;
    const int64_t sourceRight = fullSourceX
        ? static_cast<int64_t>(sourceTexture.width)
        : descriptor.source_right;
    const int64_t sourceBottom = fullSourceY
        ? static_cast<int64_t>(sourceTexture.height)
        : descriptor.source_bottom;
    if (sourceLeft < 0 || sourceTop < 0 ||
        sourceRight <= sourceLeft || sourceBottom <= sourceTop ||
        sourceRight > static_cast<int64_t>(sourceTexture.width) ||
        sourceBottom > static_cast<int64_t>(sourceTexture.height)) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }

    const bool stretched = descriptor.aspect_ratio_x == 0.0f &&
        descriptor.aspect_ratio_y == 0.0f;
    if (!stretched &&
        (!std::isfinite(descriptor.aspect_ratio_x) ||
         !std::isfinite(descriptor.aspect_ratio_y) ||
         descriptor.aspect_ratio_x <= 0.0f ||
         descriptor.aspect_ratio_y <= 0.0f)) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }

    double ratioX = 1.0;
    double ratioY = 1.0;
    if (!stretched) {
        ratioX = std::min(
            1.0,
            static_cast<double>(destinationTexture.height) *
                descriptor.aspect_ratio_x /
                (static_cast<double>(destinationTexture.width) *
                 descriptor.aspect_ratio_y));
        ratioY = std::min(
            1.0,
            static_cast<double>(destinationTexture.width) *
                descriptor.aspect_ratio_y /
                (static_cast<double>(destinationTexture.height) *
                 descriptor.aspect_ratio_x));
    }
    const NSUInteger destinationWidth = static_cast<NSUInteger>(
        destinationTexture.width * ratioX);
    const NSUInteger destinationHeight = static_cast<NSUInteger>(
        destinationTexture.height * ratioY);
    if (destinationWidth == 0 || destinationHeight == 0) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }
    const NSUInteger destinationX =
        (destinationTexture.width - destinationWidth) / 2;
    const NSUInteger destinationY =
        (destinationTexture.height - destinationHeight) / 2;

    const std::array<float, 4> sourceRegion = {
        static_cast<float>(sourceLeft) / sourceTexture.width,
        static_cast<float>(sourceTop) / sourceTexture.height,
        static_cast<float>(sourceRight - sourceLeft) / sourceTexture.width,
        static_cast<float>(sourceBottom - sourceTop) / sourceTexture.height,
    };
    const std::array<uint32_t, 2> flipAxes = {
        (descriptor.flags & SOL_METAL_PRESENT_FLIP_X) != 0 ? 1u : 0u,
        (descriptor.flags & SOL_METAL_PRESENT_FLIP_Y) != 0 ? 1u : 0u,
    };

    MTLRenderPassDescriptor *pass =
        [MTLRenderPassDescriptor renderPassDescriptor];
    pass.colorAttachments[0].texture = destinationTexture;
    pass.colorAttachments[0].loadAction = loadAction;
    pass.colorAttachments[0].storeAction = MTLStoreActionStore;
    pass.colorAttachments[0].clearColor = MTLClearColorMake(0.0, 0.0, 0.0, 1.0);
    id<MTLRenderCommandEncoder> encoder = [commandBuffer
        renderCommandEncoderWithDescriptor:pass];
    if (encoder == nil) {
        return SOL_METAL_STATUS_ALLOCATION_FAILED;
    }

    encoder.label = @"SolMetal Texture Presentation";
    [encoder setRenderPipelineState:_presentationPipeline];
    [encoder setFragmentTexture:sourceTexture atIndex:0];
    [encoder
        setFragmentSamplerState:
            descriptor.filter == SOL_METAL_SAMPLER_FILTER_LINEAR
            ? _presentationLinearSampler
            : _presentationNearestSampler
        atIndex:0];
    [encoder setFragmentBytes:&sourceRegion
                       length:sizeof(sourceRegion)
                      atIndex:0];
    [encoder setFragmentBytes:&flipAxes
                       length:sizeof(flipAxes)
                      atIndex:1];
    [encoder setViewport:(MTLViewport){
        static_cast<double>(destinationX),
        static_cast<double>(destinationY),
        static_cast<double>(destinationWidth),
        static_cast<double>(destinationHeight),
        0.0,
        1.0,
    }];
    [encoder drawPrimitives:MTLPrimitiveTypeTriangle
               vertexStart:0
               vertexCount:3];
    [encoder endEncoding];
    return SOL_METAL_STATUS_OK;
}

- (BOOL)prepareColorBlitResources:(NSError **)error {
    @synchronized (self) {
        if (_colorBlitVertexFunction != nil &&
            _colorBlitFragmentFunction != nil &&
            _colorBlitSignedFragmentFunction != nil &&
            _colorBlitUnsignedFragmentFunction != nil &&
            _colorBlitNearestSampler != nil &&
            _colorBlitLinearSampler != nil) {
            return YES;
        }

        static NSString *const source = @R"(
#include <metal_stdlib>
using namespace metal;

struct SolColorBlitVertex {
    float4 position [[position]];
    float2 textureCoordinate;
};

struct SolColorBlitParameters {
    float2 sourceOrigin;
    float2 sourceExtent;
    float2 inverseSourceSize;
};

vertex SolColorBlitVertex sol_color_blit_vertex(
    uint vertexID [[vertex_id]]) {
    const float2 positions[3] = {
        float2(-1.0, -1.0),
        float2( 3.0, -1.0),
        float2(-1.0,  3.0),
    };
    const float2 textureCoordinates[3] = {
        float2(0.0,  1.0),
        float2(2.0,  1.0),
        float2(0.0, -1.0),
    };
    SolColorBlitVertex output;
    output.position = float4(positions[vertexID], 0.0, 1.0);
    output.textureCoordinate = textureCoordinates[vertexID];
    return output;
}

fragment float4 sol_color_blit_fragment(
    SolColorBlitVertex input [[stage_in]],
    texture2d<float> sourceTexture [[texture(0)]],
    sampler sourceSampler [[sampler(0)]],
    constant SolColorBlitParameters &parameters [[buffer(0)]]) {
    const float2 sourcePixel = parameters.sourceOrigin +
        input.textureCoordinate * parameters.sourceExtent;
    return sourceTexture.sample(
        sourceSampler,
        sourcePixel * parameters.inverseSourceSize);
}

static uint2 sol_color_blit_integer_coordinate(
    SolColorBlitVertex input,
    constant SolColorBlitParameters &parameters) {
    const float2 sourcePixel = parameters.sourceOrigin +
        input.textureCoordinate * parameters.sourceExtent;
    const float2 lastSourcePixel = parameters.sourceOrigin +
        max(parameters.sourceExtent - float2(1.0f), float2(0.0f));
    return uint2(clamp(
        floor(sourcePixel),
        parameters.sourceOrigin,
        lastSourcePixel));
}

fragment int4 sol_color_blit_signed_fragment(
    SolColorBlitVertex input [[stage_in]],
    texture2d<int, access::read> sourceTexture [[texture(0)]],
    constant SolColorBlitParameters &parameters [[buffer(0)]]) {
    return sourceTexture.read(
        sol_color_blit_integer_coordinate(input, parameters));
}

fragment uint4 sol_color_blit_unsigned_fragment(
    SolColorBlitVertex input [[stage_in]],
    texture2d<uint, access::read> sourceTexture [[texture(0)]],
    constant SolColorBlitParameters &parameters [[buffer(0)]]) {
    return sourceTexture.read(
        sol_color_blit_integer_coordinate(input, parameters));
}
)";

        BOOL cacheHit = NO;
        id<MTLLibrary> library = [self
            libraryWithSource:source
            cacheHit:&cacheHit
            error:error];
        if (library == nil) {
            return NO;
        }
        id<MTLFunction> vertexFunction = [library
            newFunctionWithName:@"sol_color_blit_vertex"];
        id<MTLFunction> fragmentFunction = [library
            newFunctionWithName:@"sol_color_blit_fragment"];
        id<MTLFunction> signedFragmentFunction = [library
            newFunctionWithName:@"sol_color_blit_signed_fragment"];
        id<MTLFunction> unsignedFragmentFunction = [library
            newFunctionWithName:@"sol_color_blit_unsigned_fragment"];
        if (vertexFunction == nil || fragmentFunction == nil ||
            signedFragmentFunction == nil ||
            unsignedFragmentFunction == nil) {
            if (error != nullptr) {
                *error = [NSError
                    errorWithDomain:@"com.solemu.SolMetal"
                    code:SOL_METAL_STATUS_SHADER_COMPILATION_FAILED
                    userInfo:@{NSLocalizedDescriptionKey:
                        @"SolMetal color-blit shaders were unavailable"}];
            }
            return NO;
        }

        MTLSamplerDescriptor *nearestDescriptor =
            [[MTLSamplerDescriptor alloc] init];
        nearestDescriptor.label = @"SolMetal Nearest Color Blit Sampler";
        nearestDescriptor.minFilter = MTLSamplerMinMagFilterNearest;
        nearestDescriptor.magFilter = MTLSamplerMinMagFilterNearest;
        nearestDescriptor.mipFilter = MTLSamplerMipFilterNotMipmapped;
        nearestDescriptor.sAddressMode = MTLSamplerAddressModeClampToEdge;
        nearestDescriptor.tAddressMode = MTLSamplerAddressModeClampToEdge;
        MTLSamplerDescriptor *linearDescriptor = [nearestDescriptor copy];
        linearDescriptor.label = @"SolMetal Linear Color Blit Sampler";
        linearDescriptor.minFilter = MTLSamplerMinMagFilterLinear;
        linearDescriptor.magFilter = MTLSamplerMinMagFilterLinear;
        id<MTLSamplerState> nearestSampler = [_device
            newSamplerStateWithDescriptor:nearestDescriptor];
        id<MTLSamplerState> linearSampler = [_device
            newSamplerStateWithDescriptor:linearDescriptor];
        if (nearestSampler == nil || linearSampler == nil) {
            if (error != nullptr) {
                *error = [NSError
                    errorWithDomain:@"com.solemu.SolMetal"
                    code:SOL_METAL_STATUS_ALLOCATION_FAILED
                    userInfo:@{NSLocalizedDescriptionKey:
                        @"SolMetal color-blit samplers were unavailable"}];
            }
            return NO;
        }

        _colorBlitVertexFunction = vertexFunction;
        _colorBlitFragmentFunction = fragmentFunction;
        _colorBlitSignedFragmentFunction = signedFragmentFunction;
        _colorBlitUnsignedFragmentFunction = unsignedFragmentFunction;
        _colorBlitNearestSampler = nearestSampler;
        _colorBlitLinearSampler = linearSampler;
        return YES;
    }
}

- (nullable id<MTLRenderPipelineState>)colorBlitPipelineForPixelFormat:
    (MTLPixelFormat)pixelFormat
    outputType:(SolMetalClearOutputType)outputType
    error:(NSError **)error {
    if (![self prepareColorBlitResources:error]) {
        return nil;
    }
    @synchronized (self) {
        NSNumber *key = @(
            (static_cast<NSUInteger>(pixelFormat) << 2u) |
            static_cast<NSUInteger>(outputType));
        id<MTLRenderPipelineState> cached =
            [_colorBlitPipelineCache objectForKey:key];
        if (cached != nil) {
            return cached;
        }
        MTLRenderPipelineDescriptor *descriptor =
            [[MTLRenderPipelineDescriptor alloc] init];
        descriptor.label = @"SolMetal Color Blit Pipeline";
        descriptor.vertexFunction = _colorBlitVertexFunction;
        switch (outputType) {
            case SolMetalClearOutputSignedInteger:
                descriptor.fragmentFunction =
                    _colorBlitSignedFragmentFunction;
                break;
            case SolMetalClearOutputUnsignedInteger:
                descriptor.fragmentFunction =
                    _colorBlitUnsignedFragmentFunction;
                break;
            case SolMetalClearOutputFloat:
                descriptor.fragmentFunction = _colorBlitFragmentFunction;
                break;
        }
        descriptor.colorAttachments[0].pixelFormat = pixelFormat;
        id<MTLRenderPipelineState> pipeline = [_device
            newRenderPipelineStateWithDescriptor:descriptor
            error:error];
        if (pipeline != nil) {
            [_colorBlitPipelineCache setObject:pipeline forKey:key];
        }
        return pipeline;
    }
}

- (BOOL)prepareTextureClearResources:(NSError **)error {
    @synchronized (self) {
        if (_textureClearVertexFunction != nil &&
            _textureClearFloatFragmentFunction != nil &&
            _textureClearSignedFragmentFunction != nil &&
            _textureClearUnsignedFragmentFunction != nil &&
            _depthStencilClearFragmentFunction != nil) {
            return YES;
        }

        static NSString *const source = @R"(
#include <metal_stdlib>
using namespace metal;

struct SolTextureClearVertex {
    float4 position [[position]];
};

struct SolTextureClearColor {
    uint4 bits;
};

vertex SolTextureClearVertex sol_texture_clear_vertex(
    uint vertexID [[vertex_id]]) {
    const float2 positions[3] = {
        float2(-1.0, -1.0),
        float2( 3.0, -1.0),
        float2(-1.0,  3.0),
    };
    SolTextureClearVertex output;
    output.position = float4(positions[vertexID], 0.0, 1.0);
    return output;
}

fragment float4 sol_texture_clear_float_fragment(
    constant SolTextureClearColor &color [[buffer(0)]]) {
    return as_type<float4>(color.bits);
}

fragment int4 sol_texture_clear_signed_fragment(
    constant SolTextureClearColor &color [[buffer(0)]]) {
    return as_type<int4>(color.bits);
}

fragment uint4 sol_texture_clear_unsigned_fragment(
    constant SolTextureClearColor &color [[buffer(0)]]) {
    return color.bits;
}

struct SolDepthClearOutput {
    float depth [[depth(any)]];
};

fragment SolDepthClearOutput sol_depth_stencil_clear_fragment(
    constant float &depth [[buffer(0)]]) {
    SolDepthClearOutput output;
    output.depth = depth;
    return output;
}
)";

        BOOL cacheHit = NO;
        id<MTLLibrary> library = [self
            libraryWithSource:source
            cacheHit:&cacheHit
            error:error];
        if (library == nil) {
            return NO;
        }
        _textureClearVertexFunction = [library
            newFunctionWithName:@"sol_texture_clear_vertex"];
        _textureClearFloatFragmentFunction = [library
            newFunctionWithName:@"sol_texture_clear_float_fragment"];
        _textureClearSignedFragmentFunction = [library
            newFunctionWithName:@"sol_texture_clear_signed_fragment"];
        _textureClearUnsignedFragmentFunction = [library
            newFunctionWithName:@"sol_texture_clear_unsigned_fragment"];
        _depthStencilClearFragmentFunction = [library
            newFunctionWithName:@"sol_depth_stencil_clear_fragment"];
        if (_textureClearVertexFunction == nil ||
            _textureClearFloatFragmentFunction == nil ||
            _textureClearSignedFragmentFunction == nil ||
            _textureClearUnsignedFragmentFunction == nil ||
            _depthStencilClearFragmentFunction == nil) {
            if (error != nullptr) {
                *error = [NSError
                    errorWithDomain:@"com.solemu.SolMetal"
                    code:SOL_METAL_STATUS_SHADER_COMPILATION_FAILED
                    userInfo:@{NSLocalizedDescriptionKey:
                        @"SolMetal clear shader functions were unavailable"}];
            }
            return NO;
        }
        return YES;
    }
}

- (nullable id<MTLRenderPipelineState>)textureClearPipelineForPixelFormat:
    (MTLPixelFormat)pixelFormat
    outputType:(SolMetalClearOutputType)outputType
    writeMask:(MTLColorWriteMask)writeMask
    sampleCount:(NSUInteger)sampleCount
    error:(NSError **)error {
    if (![self prepareTextureClearResources:error]) {
        return nil;
    }
    NSString *key = [NSString stringWithFormat:
        @"%lu:%lu:%lu:%lu",
        static_cast<unsigned long>(pixelFormat),
        static_cast<unsigned long>(outputType),
        static_cast<unsigned long>(writeMask),
        static_cast<unsigned long>(sampleCount)];
    @synchronized (self) {
        id<MTLRenderPipelineState> cached =
            [_textureClearPipelineCache objectForKey:key];
        if (cached != nil) {
            return cached;
        }
        id<MTLFunction> fragmentFunction =
            outputType == SolMetalClearOutputSignedInteger
                ? _textureClearSignedFragmentFunction
                : outputType == SolMetalClearOutputUnsignedInteger
                    ? _textureClearUnsignedFragmentFunction
                    : _textureClearFloatFragmentFunction;
        MTLRenderPipelineDescriptor *descriptor =
            [[MTLRenderPipelineDescriptor alloc] init];
        descriptor.label = @"SolMetal Texture Clear Pipeline";
        descriptor.vertexFunction = _textureClearVertexFunction;
        descriptor.fragmentFunction = fragmentFunction;
        descriptor.rasterSampleCount = sampleCount;
        descriptor.colorAttachments[0].pixelFormat = pixelFormat;
        descriptor.colorAttachments[0].writeMask = writeMask;
        id<MTLRenderPipelineState> pipeline = [_device
            newRenderPipelineStateWithDescriptor:descriptor
            error:error];
        if (pipeline != nil) {
            [_textureClearPipelineCache setObject:pipeline forKey:key];
        }
        return pipeline;
    }
}

- (nullable id<MTLRenderPipelineState>)depthStencilClearPipelineForPixelFormat:
    (MTLPixelFormat)pixelFormat
    hasStencil:(BOOL)hasStencil
    sampleCount:(NSUInteger)sampleCount
    error:(NSError **)error {
    if (![self prepareTextureClearResources:error]) {
        return nil;
    }
    NSString *key = [NSString stringWithFormat:
        @"%lu:%u:%lu",
        static_cast<unsigned long>(pixelFormat),
        hasStencil ? 1u : 0u,
        static_cast<unsigned long>(sampleCount)];
    @synchronized (self) {
        id<MTLRenderPipelineState> cached =
            [_depthStencilClearPipelineCache objectForKey:key];
        if (cached != nil) {
            return cached;
        }
        MTLRenderPipelineDescriptor *descriptor =
            [[MTLRenderPipelineDescriptor alloc] init];
        descriptor.label = @"SolMetal Depth Stencil Clear Pipeline";
        descriptor.vertexFunction = _textureClearVertexFunction;
        descriptor.fragmentFunction = _depthStencilClearFragmentFunction;
        descriptor.rasterSampleCount = sampleCount;
        descriptor.depthAttachmentPixelFormat = pixelFormat;
        if (hasStencil) {
            descriptor.stencilAttachmentPixelFormat = pixelFormat;
        }
        id<MTLRenderPipelineState> pipeline = [_device
            newRenderPipelineStateWithDescriptor:descriptor
            error:error];
        if (pipeline != nil) {
            [_depthStencilClearPipelineCache setObject:pipeline forKey:key];
        }
        return pipeline;
    }
}

