- (BOOL)prepareQuadIndexExpansionResources:(NSError **)error {
    @synchronized (self) {
        if (_quadIndexExpansionPipeline != nil) {
            return YES;
        }

        static NSString *const source = @R"(
#include <metal_stdlib>
using namespace metal;

static uint sol_read_quad_index(
    const device uchar *source,
    ulong offset,
    uint byteCount) {
    if (byteCount == 1) {
        return uint(source[offset]);
    }
    if (byteCount == 2) {
        return uint(source[offset]) |
            (uint(source[offset + 1]) << 8);
    }
    return uint(source[offset]) |
        (uint(source[offset + 1]) << 8) |
        (uint(source[offset + 2]) << 16) |
        (uint(source[offset + 3]) << 24);
}

kernel void sol_expand_quad_indices(
    const device uchar *source [[buffer(0)]],
    device uint *destination [[buffer(1)]],
    constant ulong &sourceOffset [[buffer(2)]],
    constant uint &sourceIndexByteCount [[buffer(3)]],
    uint quad [[thread_position_in_grid]]) {
    const ulong input = sourceOffset +
        ulong(quad) * ulong(4) * ulong(sourceIndexByteCount);
    const uint first = sol_read_quad_index(
        source,
        input,
        sourceIndexByteCount);
    const uint second = sol_read_quad_index(
        source,
        input + sourceIndexByteCount,
        sourceIndexByteCount);
    const uint third = sol_read_quad_index(
        source,
        input + ulong(2) * sourceIndexByteCount,
        sourceIndexByteCount);
    const uint fourth = sol_read_quad_index(
        source,
        input + ulong(3) * sourceIndexByteCount,
        sourceIndexByteCount);
    const uint output = quad * 6u;
    destination[output] = first;
    destination[output + 1] = second;
    destination[output + 2] = third;
    destination[output + 3] = first;
    destination[output + 4] = third;
    destination[output + 5] = fourth;
}
)";

        BOOL cacheHit = NO;
        id<MTLLibrary> library = [self
            libraryWithSource:source
            cacheHit:&cacheHit
            error:error];
        if (library == nil) {
            return NO;
        }
        id<MTLFunction> function = [library
            newFunctionWithName:@"sol_expand_quad_indices"];
        if (function == nil) {
            if (error != nullptr) {
                *error = [NSError
                    errorWithDomain:@"com.solemu.SolMetal"
                    code:SOL_METAL_STATUS_SHADER_COMPILATION_FAILED
                    userInfo:@{NSLocalizedDescriptionKey:
                        @"SolMetal quad-index expansion shader was unavailable"}];
            }
            return NO;
        }
        id<MTLComputePipelineState> pipeline = [_device
            newComputePipelineStateWithFunction:function
            error:error];
        if (pipeline == nil) {
            return NO;
        }
        _quadIndexExpansionPipeline = pipeline;
        return YES;
    }
}

- (BOOL)prepareIndirectCountResources:(NSError **)error {
    @synchronized (self) {
        if (_indirectCountPipeline != nil) {
            return YES;
        }

        static NSString *const source = @R"(
#include <metal_stdlib>
using namespace metal;

struct SolIndirectCountParameters {
    ulong sourceOffset;
    ulong countOffset;
    uint sourceStride;
    uint commandSize;
    uint maxDrawCount;
};

kernel void sol_prepare_indirect_count(
    const device uchar *source [[buffer(0)]],
    const device uchar *countSource [[buffer(1)]],
    device uchar *destination [[buffer(2)]],
    constant SolIndirectCountParameters &parameters [[buffer(3)]],
    uint index [[thread_position_in_grid]]) {
    if (index >= parameters.maxDrawCount) {
        return;
    }

    const device uint *countPointer =
        reinterpret_cast<const device uint *>(
            countSource + parameters.countOffset);
    const uint activeDrawCount = min(*countPointer, parameters.maxDrawCount);
    const ulong destinationOffset = ulong(index) * parameters.commandSize;
    if (index < activeDrawCount) {
        const ulong sourceOffset = parameters.sourceOffset +
            ulong(index) * parameters.sourceStride;
        for (uint byteIndex = 0;
             byteIndex < parameters.commandSize;
             ++byteIndex) {
            destination[destinationOffset + byteIndex] =
                source[sourceOffset + byteIndex];
        }
    } else {
        for (uint byteIndex = 0;
             byteIndex < parameters.commandSize;
             ++byteIndex) {
            destination[destinationOffset + byteIndex] = 0;
        }
    }
}
)";

        BOOL cacheHit = NO;
        id<MTLLibrary> library = [self
            libraryWithSource:source
            cacheHit:&cacheHit
            error:error];
        if (library == nil) {
            return NO;
        }
        id<MTLFunction> function = [library
            newFunctionWithName:@"sol_prepare_indirect_count"];
        if (function == nil) {
            if (error != nullptr) {
                *error = [NSError
                    errorWithDomain:@"com.solemu.SolMetal"
                    code:SOL_METAL_STATUS_SHADER_COMPILATION_FAILED
                    userInfo:@{NSLocalizedDescriptionKey:
                        @"SolMetal indirect-count shader was unavailable"}];
            }
            return NO;
        }
        id<MTLComputePipelineState> pipeline = [_device
            newComputePipelineStateWithFunction:function
            error:error];
        if (pipeline == nil) {
            return NO;
        }
        _indirectCountPipeline = pipeline;
        return YES;
    }
}

