- (BOOL)prepareDepthStencilScaleResources:(NSError **)error {
    @synchronized (self) {
        if (_depthStencilScalePipeline != nil) {
            return YES;
        }

        static NSString *const source = @R"(
#include <metal_stdlib>
using namespace metal;

struct SolDepthStencilScaleParameters {
    uint sourceX;
    uint sourceY;
    uint sourceWidth;
    uint sourceHeight;
    uint destinationWidth;
    uint destinationHeight;
    uint depthStride;
    uint stencilStride;
};

kernel void sol_scale_depth_stencil_nearest(
    depth2d<float, access::read> sourceDepth [[texture(0)]],
    texture2d<uint, access::read> sourceStencil [[texture(1)]],
    device float *destinationDepth [[buffer(0)]],
    device uchar *destinationStencil [[buffer(1)]],
    constant SolDepthStencilScaleParameters &parameters [[buffer(2)]],
    uint2 position [[thread_position_in_grid]]) {
    if (position.x >= parameters.destinationWidth ||
        position.y >= parameters.destinationHeight) {
        return;
    }
    const uint sourceOffsetX = min(
        ((position.x * 2 + 1) * parameters.sourceWidth) /
            (parameters.destinationWidth * 2),
        parameters.sourceWidth - 1);
    const uint sourceOffsetY = min(
        ((position.y * 2 + 1) * parameters.sourceHeight) /
            (parameters.destinationHeight * 2),
        parameters.sourceHeight - 1);
    const uint2 sourcePosition = uint2(
        parameters.sourceX + sourceOffsetX,
        parameters.sourceY + sourceOffsetY);
    destinationDepth[
        position.y * parameters.depthStride + position.x] =
        sourceDepth.read(sourcePosition);
    destinationStencil[
        position.y * parameters.stencilStride + position.x] =
        uchar(sourceStencil.read(sourcePosition).x);
}
)";

        BOOL cacheHit = NO;
        id<MTLLibrary> library = [self
            libraryWithSource:source
            cacheHit:&cacheHit
            error:error];
        if (library == nil) {
