- (BOOL)prepareDepthSidecarResources:(NSError **)error {
    @synchronized (self) {
        if (_depthSidecarToD16Pipeline != nil &&
            _depthSidecarToD32Pipeline != nil &&
            _depthSidecarWriteState != nil) {
            return YES;
        }

        static NSString *const source = @R"(
#include <metal_stdlib>
using namespace metal;

struct SolDepthSidecarVertex {
    float4 position [[position]];
};

struct SolDepthSidecarOutput {
    float depth [[depth(any)]];
};

vertex SolDepthSidecarVertex sol_depth_sidecar_vertex(
    uint vertexID [[vertex_id]]) {
    const float2 positions[3] = {
        float2(-1.0, -1.0),
        float2( 3.0, -1.0),
        float2(-1.0,  3.0),
    };
    SolDepthSidecarVertex output;
    output.position = float4(positions[vertexID], 0.0, 1.0);
    return output;
}

fragment SolDepthSidecarOutput sol_depth_sidecar_fragment(
    float4 position [[position]],
    depth2d<float, access::read> sourceDepth [[texture(0)]]) {
    SolDepthSidecarOutput output;
    output.depth = sourceDepth.read(uint2(position.xy));
    return output;
}

)";

        BOOL cacheHit = NO;
        id<MTLLibrary> library = [self
            libraryWithSource:source
            fpFastMathFlags:spv::FPFastMathModeMaskNone
            preserveInvariance:YES
            cacheHit:&cacheHit
            error:error];
        if (library == nil) {
            return NO;
        }
        id<MTLFunction> vertex = [library
            newFunctionWithName:@"sol_depth_sidecar_vertex"];
        id<MTLFunction> fragment = [library
            newFunctionWithName:@"sol_depth_sidecar_fragment"];
        if (vertex == nil || fragment == nil) {
            if (error != nullptr) {
                *error = [NSError
                    errorWithDomain:@"com.solemu.SolMetal"
                    code:SOL_METAL_STATUS_SHADER_COMPILATION_FAILED
                    userInfo:@{NSLocalizedDescriptionKey:
                        @"SolMetal D16 sidecar shader functions were unavailable"}];
            }
            return NO;
        }

        MTLRenderPipelineDescriptor *toD16Descriptor =
            [[MTLRenderPipelineDescriptor alloc] init];
        toD16Descriptor.label =
            @"SolMetal D32 to D16 Sidecar Pipeline";
        toD16Descriptor.vertexFunction = vertex;
        toD16Descriptor.fragmentFunction = fragment;
        toD16Descriptor.depthAttachmentPixelFormat =
            MTLPixelFormatDepth16Unorm;
        id<MTLRenderPipelineState> toD16 = [_device
            newRenderPipelineStateWithDescriptor:toD16Descriptor
            error:error];
        MTLRenderPipelineDescriptor *toD32Descriptor =
            [[MTLRenderPipelineDescriptor alloc] init];
        toD32Descriptor.label =
            @"SolMetal D16 Sidecar to D32 Pipeline";
        toD32Descriptor.vertexFunction = vertex;
        toD32Descriptor.fragmentFunction = fragment;
        toD32Descriptor.depthAttachmentPixelFormat =
            MTLPixelFormatDepth32Float;
        id<MTLRenderPipelineState> toD32 = toD16 == nil
            ? nil
            : [_device
                newRenderPipelineStateWithDescriptor:toD32Descriptor
                error:error];
        MTLDepthStencilDescriptor *depthStateDescriptor =
            [[MTLDepthStencilDescriptor alloc] init];
        depthStateDescriptor.depthCompareFunction = MTLCompareFunctionAlways;
        depthStateDescriptor.depthWriteEnabled = YES;
        id<MTLDepthStencilState> writeState = toD32 == nil
            ? nil
            : [_device newDepthStencilStateWithDescriptor:
                depthStateDescriptor];
        if (toD16 == nil || toD32 == nil || writeState == nil) {
            return NO;
        }
        _depthSidecarToD16Pipeline = toD16;
        _depthSidecarToD32Pipeline = toD32;
        _depthSidecarWriteState = writeState;
        return YES;
    }
}

- (nullable id<MTLRenderPipelineState>)depthSidecarPipelineForPixelFormat:
    (MTLPixelFormat)pixelFormat error:(NSError **)error {
    if (![self prepareDepthSidecarResources:error]) {
        return nil;
    }
    if (pixelFormat == MTLPixelFormatDepth16Unorm) {
        return _depthSidecarToD16Pipeline;
    }
    if (pixelFormat == MTLPixelFormatDepth32Float) {
        return _depthSidecarToD32Pipeline;
    }
    if (error != nullptr) {
        *error = [NSError
            errorWithDomain:@"com.solemu.SolMetal"
            code:SOL_METAL_STATUS_UNSUPPORTED
            userInfo:@{NSLocalizedDescriptionKey:
                @"SolMetal D16 sidecar copy received an unsupported depth format"}];
    }
    return nil;
}

@end

@interface SolMetalShaderTranslationObject : NSObject

@property(nonatomic, strong, readonly) id<MTLDevice> device;
@property(nonatomic, copy, readonly) NSString *mslSource;
@property(nonatomic, strong, readonly) id<MTLLibrary> library;
@property(nonatomic, strong, readonly) id<MTLFunction> function;
@property(nonatomic, assign, readonly) SolMetalShaderStage stage;
@property(nonatomic, assign, readonly) uint32_t fpFastMathFlags;
@property(nonatomic, assign, readonly) BOOL preserveInvariance;
@property(nonatomic, assign, readonly) BOOL requestsEarlyFragmentTests;
@property(nonatomic, assign, readonly) BOOL mayTerminateInvocation;
@property(nonatomic, assign, readonly) BOOL writesRenderTargetArrayIndex;
@property(nonatomic, assign, readonly) BOOL exposesPointSize;
@property(nonatomic, copy, readonly) NSString *functionName;

- (nullable instancetype)initWithDevice:(id<MTLDevice>)device
                                mslSource:(NSString *)source
                                   library:(id<MTLLibrary>)library
                                  function:(id<MTLFunction>)function
                                     stage:(SolMetalShaderStage)stage
                           fpFastMathFlags:(uint32_t)fpFastMathFlags
                        preserveInvariance:(BOOL)preserveInvariance
                requestsEarlyFragmentTests:(BOOL)requestsEarlyFragmentTests
                   mayTerminateInvocation:(BOOL)mayTerminateInvocation
                              functionName:(NSString *)functionName;

- (nullable instancetype)initWithDevice:(id<MTLDevice>)device
                                mslSource:(NSString *)source
                                   library:(id<MTLLibrary>)library
                                  function:(id<MTLFunction>)function
                                     stage:(SolMetalShaderStage)stage
                           fpFastMathFlags:(uint32_t)fpFastMathFlags
                        preserveInvariance:(BOOL)preserveInvariance
                requestsEarlyFragmentTests:(BOOL)requestsEarlyFragmentTests
                   mayTerminateInvocation:(BOOL)mayTerminateInvocation
                          exposesPointSize:(BOOL)exposesPointSize
                              functionName:(NSString *)functionName;

@end

@implementation SolMetalShaderTranslationObject

- (nullable instancetype)initWithDevice:(id<MTLDevice>)device
                                mslSource:(NSString *)source
                                   library:(id<MTLLibrary>)library
                                  function:(id<MTLFunction>)function
                                     stage:(SolMetalShaderStage)stage
                           fpFastMathFlags:(uint32_t)fpFastMathFlags
                        preserveInvariance:(BOOL)preserveInvariance
                requestsEarlyFragmentTests:(BOOL)requestsEarlyFragmentTests
                   mayTerminateInvocation:(BOOL)mayTerminateInvocation
                              functionName:(NSString *)functionName {
    return [self initWithDevice:device
                      mslSource:source
                         library:library
                        function:function
                           stage:stage
                 fpFastMathFlags:fpFastMathFlags
              preserveInvariance:preserveInvariance
      requestsEarlyFragmentTests:requestsEarlyFragmentTests
         mayTerminateInvocation:mayTerminateInvocation
                exposesPointSize:NO
                    functionName:functionName];
}

- (nullable instancetype)initWithDevice:(id<MTLDevice>)device
                                mslSource:(NSString *)source
                                   library:(id<MTLLibrary>)library
                                  function:(id<MTLFunction>)function
                                     stage:(SolMetalShaderStage)stage
                           fpFastMathFlags:(uint32_t)fpFastMathFlags
                        preserveInvariance:(BOOL)preserveInvariance
                requestsEarlyFragmentTests:(BOOL)requestsEarlyFragmentTests
                   mayTerminateInvocation:(BOOL)mayTerminateInvocation
                          exposesPointSize:(BOOL)exposesPointSize
                              functionName:(NSString *)functionName {
    self = [super init];
    if (self == nil || device == nil || source.length == 0 || library == nil ||
        function == nil || functionName.length == 0) {
        return nil;
    }
    _device = device;
    _mslSource = [source copy];
    _library = library;
    _function = function;
    _stage = stage;
    _fpFastMathFlags = fpFastMathFlags;
    _preserveInvariance = preserveInvariance;
    _requestsEarlyFragmentTests = requestsEarlyFragmentTests;
    _mayTerminateInvocation = mayTerminateInvocation;
    _writesRenderTargetArrayIndex =
        stage == SOL_METAL_SHADER_STAGE_VERTEX &&
        [source containsString:@"[[render_target_array_index]]"];
    _exposesPointSize =
        stage == SOL_METAL_SHADER_STAGE_VERTEX && exposesPointSize;
    _functionName = [functionName copy];
    return self;
}

@end

static NSError *D16ShaderPatchError(NSString *message) {
    return [NSError
        errorWithDomain:@"com.solemu.SolMetal"
        code:SOL_METAL_STATUS_SHADER_COMPILATION_FAILED
        userInfo:@{NSLocalizedDescriptionKey: message}];
}

static bool ShaderSourceMatchesPattern(
    NSString *source,
    NSString *pattern) {
    if (source.length == 0 || pattern.length == 0) {
        return false;
    }
    NSRegularExpression *expression =
        [NSRegularExpression regularExpressionWithPattern:pattern
                                                   options:0
                                                     error:nil];
    return expression != nil &&
        [expression firstMatchInString:source
                               options:0
                                 range:NSMakeRange(0, source.length)] != nil;
}

static bool ShaderSourceHasFragmentDepthOutput(NSString *source) {
    return ShaderSourceMatchesPattern(
        source,
        @"\\[\\[\\s*depth\\s*\\(");
}

static bool IsShaderIdentifierStart(unichar character) {
    return character == '_' ||
        (character >= 'A' && character <= 'Z') ||
        (character >= 'a' && character <= 'z');
}

static bool IsShaderIdentifierContinuation(unichar character) {
    return IsShaderIdentifierStart(character) ||
        (character >= '0' && character <= '9');
}

static NSUInteger ShaderMatchingDelimiter(
    NSString *source,
    NSUInteger openingIndex,
    unichar openingCharacter,
    unichar closingCharacter) {
    if (source.length == 0 || openingIndex >= source.length ||
        [source characterAtIndex:openingIndex] != openingCharacter) {
        return NSNotFound;
    }
    NSUInteger depth = 0;
    bool lineComment = false;
    bool blockComment = false;
    bool stringLiteral = false;
    bool characterLiteral = false;
    bool escaped = false;
    for (NSUInteger index = openingIndex; index < source.length; ++index) {
        const unichar character = [source characterAtIndex:index];
        const unichar next = index + 1 < source.length
            ? [source characterAtIndex:index + 1]
            : 0;
        if (lineComment) {
            if (character == '\n' || character == '\r') {
                lineComment = false;
            }
            continue;
        }
        if (blockComment) {
            if (character == '*' && next == '/') {
                blockComment = false;
                index += 1;
            }
            continue;
        }
        if (stringLiteral || characterLiteral) {
            if (escaped) {
                escaped = false;
            } else if (character == '\\') {
                escaped = true;
            } else if ((stringLiteral && character == '"') ||
                       (characterLiteral && character == '\'')) {
                stringLiteral = false;
                characterLiteral = false;
            }
            continue;
        }
        if (character == '/' && next == '/') {
            lineComment = true;
            index += 1;
            continue;
        }
        if (character == '/' && next == '*') {
            blockComment = true;
            index += 1;
            continue;
        }
        if (character == '"') {
            stringLiteral = true;
            continue;
        }
        if (character == '\'') {
            characterLiteral = true;
            continue;
        }
        if (character == openingCharacter) {
            depth += 1;
        } else if (character == closingCharacter) {
            if (depth == 0) {
                return NSNotFound;
            }
            depth -= 1;
            if (depth == 0) {
                return index;
            }
        }
    }
    return NSNotFound;
}

static NSUInteger ShaderNextCodeCharacter(
    NSString *source,
    NSUInteger startIndex,
    unichar targetCharacter) {
    if (source.length == 0 || startIndex >= source.length) {
        return NSNotFound;
    }
    bool lineComment = false;
    bool blockComment = false;
    bool stringLiteral = false;
    bool characterLiteral = false;
    bool escaped = false;
    for (NSUInteger index = startIndex; index < source.length; ++index) {
        const unichar character = [source characterAtIndex:index];
        const unichar next = index + 1 < source.length
            ? [source characterAtIndex:index + 1]
            : 0;
        if (lineComment) {
            if (character == '\n' || character == '\r') {
                lineComment = false;
            }
            continue;
        }
        if (blockComment) {
            if (character == '*' && next == '/') {
                blockComment = false;
                index += 1;
            }
            continue;
        }
        if (stringLiteral || characterLiteral) {
            if (escaped) {
                escaped = false;
            } else if (character == '\\') {
                escaped = true;
            } else if ((stringLiteral && character == '"') ||
                       (characterLiteral && character == '\'')) {
                stringLiteral = false;
                characterLiteral = false;
            }
            continue;
        }
        if (character == '/' && next == '/') {
            lineComment = true;
            index += 1;
            continue;
        }
        if (character == '/' && next == '*') {
            blockComment = true;
            index += 1;
            continue;
        }
        if (character == '"') {
            stringLiteral = true;
            continue;
        }
        if (character == '\'') {
            characterLiteral = true;
            continue;
        }
        if (character == targetCharacter) {
            return index;
        }
    }
    return NSNotFound;
}

static std::vector<NSRange> ShaderBareReturnRanges(
    NSString *source,
    NSRange range) {
    std::vector<NSRange> ranges;
    if (source.length == 0 || range.location > source.length ||
        range.length > source.length - range.location) {
        return ranges;
    }
    const NSUInteger end = NSMaxRange(range);
    bool lineComment = false;
    bool blockComment = false;
    bool stringLiteral = false;
    bool characterLiteral = false;
    bool escaped = false;
    for (NSUInteger index = range.location; index < end; ++index) {
        const unichar character = [source characterAtIndex:index];
        const unichar next = index + 1 < end
            ? [source characterAtIndex:index + 1]
            : 0;
        if (lineComment) {
            if (character == '\n' || character == '\r') {
                lineComment = false;
            }
            continue;
        }
        if (blockComment) {
            if (character == '*' && next == '/') {
                blockComment = false;
                index += 1;
            }
            continue;
        }
        if (stringLiteral || characterLiteral) {
            if (escaped) {
                escaped = false;
            } else if (character == '\\') {
                escaped = true;
            } else if ((stringLiteral && character == '"') ||
                       (characterLiteral && character == '\'')) {
                stringLiteral = false;
                characterLiteral = false;
            }
            continue;
        }
        if (character == '/' && next == '/') {
            lineComment = true;
            index += 1;
            continue;
        }
        if (character == '/' && next == '*') {
            blockComment = true;
            index += 1;
            continue;
        }
        if (character == '"') {
            stringLiteral = true;
            continue;
        }
        if (character == '\'') {
            characterLiteral = true;
            continue;
        }
        if (!IsShaderIdentifierStart(character)) {
            continue;
        }
        const NSUInteger identifierStart = index;
        while (index + 1 < end && IsShaderIdentifierContinuation(
            [source characterAtIndex:index + 1])) {
            index += 1;
        }
        const NSRange identifierRange = NSMakeRange(
            identifierStart,
            index - identifierStart + 1);
        if (![[source substringWithRange:identifierRange]
                isEqualToString:@"return"]) {
            continue;
        }
        NSUInteger semicolon = index + 1;
        while (semicolon < end && [[NSCharacterSet
            whitespaceAndNewlineCharacterSet]
            characterIsMember:[source characterAtIndex:semicolon]]) {
            semicolon += 1;
        }
        if (semicolon < end && [source characterAtIndex:semicolon] == ';') {
            ranges.push_back(NSMakeRange(
                identifierStart,
                semicolon - identifierStart + 1));
            index = semicolon;
        }
    }
    return ranges;
}

static NSString *D16QuantizedShaderSource(
    NSString *source,
    NSString *functionName,
    SolMetalShaderStage stage,
    NSError **error) {
    if (source.length == 0 || functionName.length == 0) {
        if (error != nullptr) {
            *error = D16ShaderPatchError(
                @"D16 depth quantization received an empty shader");
        }
        return nil;
    }
    NSString *attributePattern = stage == SOL_METAL_SHADER_STAGE_VERTEX
        ? @"\\b([A-Za-z_][A-Za-z0-9_]*)\\s*\\[\\[position(?:\\s*,[^\\]]*)?\\]\\]"
        : @"\\b([A-Za-z_][A-Za-z0-9_]*)\\s*"
           "\\[\\[\\s*depth\\s*\\([^\\)]*\\)\\s*\\]\\]";
    NSRegularExpression *attributeExpression =
        [NSRegularExpression regularExpressionWithPattern:attributePattern
                                                   options:0
                                                     error:error];
    NSTextCheckingResult *attributeMatch = [attributeExpression
        firstMatchInString:source
        options:0
        range:NSMakeRange(0, source.length)];
    if (attributeMatch == nil) {
        if (stage == SOL_METAL_SHADER_STAGE_FRAGMENT) {
            // No explicit depth output exists. The raster-depth lowering
            // caller decides whether this shader needs a late D16 output.
            return source;
        }
        if (error != nullptr) {
            *error = D16ShaderPatchError(
                @"D16 vertex shader has no Metal position output");
        }
        return nil;
    }
    NSString *fieldName = [source substringWithRange:
        [attributeMatch rangeAtIndex:1]];

    NSString *stageKeyword = stage == SOL_METAL_SHADER_STAGE_VERTEX
        ? @"vertex"
        : @"fragment";
    NSString *escapedFunctionName =
        [NSRegularExpression escapedPatternForString:functionName];
    NSString *functionPattern = [NSString stringWithFormat:
        @"\\b%@\\s+[^\\{;]+?\\b%@\\s*\\(",
        stageKeyword,
        escapedFunctionName];
    NSRegularExpression *functionExpression =
        [NSRegularExpression regularExpressionWithPattern:functionPattern
                                                   options:0
                                                     error:error];
    NSTextCheckingResult *functionMatch = [functionExpression
        firstMatchInString:source
        options:0
        range:NSMakeRange(0, source.length)];
    if (functionMatch == nil) {
        if (error != nullptr) {
            *error = D16ShaderPatchError([NSString stringWithFormat:
                @"D16 shader entry point %@ was not found",
                functionName]);
        }
        return nil;
    }

    NSRange openingBrace = [source
        rangeOfString:@"{"
        options:0
        range:NSMakeRange(
            NSMaxRange(functionMatch.range),
            source.length - NSMaxRange(functionMatch.range))];
    if (openingBrace.location == NSNotFound) {
        if (error != nullptr) {
            *error = D16ShaderPatchError(
                @"D16 shader entry point has no function body");
        }
        return nil;
    }
    NSUInteger closingBrace = NSNotFound;
    NSUInteger braceDepth = 0;
    for (NSUInteger index = openingBrace.location;
         index < source.length;
         ++index) {
        const unichar character = [source characterAtIndex:index];
        if (character == '{') {
            braceDepth += 1;
        } else if (character == '}') {
            if (braceDepth == 0) {
                break;
            }
            braceDepth -= 1;
            if (braceDepth == 0) {
                closingBrace = index;
                break;
            }
        }
    }
    if (closingBrace == NSNotFound) {
        if (error != nullptr) {
            *error = D16ShaderPatchError(
                @"D16 shader entry point has an unterminated function body");
        }
        return nil;
    }

    NSRange bodyRange = NSMakeRange(
        openingBrace.location + 1,
        closingBrace - openingBrace.location - 1);
    NSRegularExpression *returnExpression =
        [NSRegularExpression
            regularExpressionWithPattern:
                @"\\breturn\\s+([A-Za-z_][A-Za-z0-9_]*)\\s*;"
            options:0
            error:error];
    NSArray<NSTextCheckingResult *> *returnMatches = [returnExpression
        matchesInString:source
        options:0
        range:bodyRange];
    NSTextCheckingResult *returnMatch = returnMatches.lastObject;
    if (returnMatch == nil) {
        if (error != nullptr) {
            *error = D16ShaderPatchError(
                @"D16 shader entry point has no value return");
        }
        return nil;
    }
    NSString *returnValue = [source substringWithRange:
        [returnMatch rangeAtIndex:1]];
    NSString *quantization = stage == SOL_METAL_SHADER_STAGE_VERTEX
        ? [NSString stringWithFormat:
            @"    const float sol_metal_d16_depth_value = "
             "clamp(%@.%@.z / %@.%@.w, 0.0f, 1.0f);\n"
             "    const float sol_metal_d16_quantized_depth = "
             "rint(sol_metal_d16_depth_value * 65535.0f) "
             "* (1.0f / 65535.0f);\n"
             "    %@.%@.z = sol_metal_d16_quantized_depth * %@.%@.w;\n",
            returnValue,
            fieldName,
            returnValue,
            fieldName,
            returnValue,
            fieldName,
            returnValue,
            fieldName]
        : [NSString stringWithFormat:
            @"    const float sol_metal_d16_depth_value = "
             "clamp(%@.%@, 0.0f, 1.0f);\n"
             "    const float sol_metal_d16_quantized_depth = "
             "rint(sol_metal_d16_depth_value * 65535.0f) "
             "* (1.0f / 65535.0f);\n"
             "    %@.%@ = sol_metal_d16_quantized_depth;\n",
            returnValue,
            fieldName,
            returnValue,
            fieldName];
    NSMutableString *patched = [source mutableCopy];
    [patched insertString:quantization atIndex:returnMatch.range.location];
    if (stage == SOL_METAL_SHADER_STAGE_FRAGMENT) {
        // Quantization can move an explicit value in either direction. A
        // conservative greater/less qualifier would therefore be false and
        // could let Metal apply an invalid early-depth optimization.
        NSRegularExpression *depthQualifierExpression =
            [NSRegularExpression
                regularExpressionWithPattern:
                    @"\\[\\[\\s*depth\\s*\\([^\\)]*\\)\\s*\\]\\]"
                options:0
                error:error];
        if (depthQualifierExpression == nil) {
            return nil;
        }
        [depthQualifierExpression
            replaceMatchesInString:patched
            options:0
            range:NSMakeRange(0, patched.length)
            withTemplate:@"[[depth(any)]]"];
    }
    return patched;
}

static NSString *D16RasterDepthFragmentSource(
    NSString *source,
    NSString *functionName,
    NSError **error) {
    if (source.length == 0 || functionName.length == 0) {
        if (error != nullptr) {
            *error = D16ShaderPatchError(
                @"D16 raster-depth quantization received an empty shader");
        }
        return nil;
    }
    if (ShaderSourceHasFragmentDepthOutput(source)) {
        return D16QuantizedShaderSource(
            source,
            functionName,
            SOL_METAL_SHADER_STAGE_FRAGMENT,
            error);
    }

    NSMutableString *patched = [source mutableCopy];
    NSRegularExpression *earlyFragmentExpression =
        [NSRegularExpression
            regularExpressionWithPattern:
                @"\\[\\[\\s*early_fragment_tests\\s*\\]\\]"
            options:0
            error:error];
    if (earlyFragmentExpression == nil) {
        return nil;
    }
    [earlyFragmentExpression
        replaceMatchesInString:patched
        options:0
        range:NSMakeRange(0, patched.length)
        withTemplate:@""];

    NSString *escapedFunctionName =
        [NSRegularExpression escapedPatternForString:functionName];
    NSString *functionPattern = [NSString stringWithFormat:
        @"\\bfragment\\s+([A-Za-z_][A-Za-z0-9_]*)\\s+%@\\s*\\(",
        escapedFunctionName];
    NSRegularExpression *functionExpression =
        [NSRegularExpression regularExpressionWithPattern:functionPattern
                                                   options:0
                                                     error:error];
    NSTextCheckingResult *functionMatch = [functionExpression
        firstMatchInString:patched
        options:0
        range:NSMakeRange(0, patched.length)];
    if (functionMatch == nil) {
        if (error != nullptr) {
            *error = D16ShaderPatchError([NSString stringWithFormat:
                @"D16 fragment entry point %@ was not found",
                functionName]);
        }
        return nil;
    }
    NSString *returnType = [patched substringWithRange:
        [functionMatch rangeAtIndex:1]];
    const NSUInteger parameterOpen = NSMaxRange(functionMatch.range) - 1;
    const NSUInteger parameterClose = ShaderMatchingDelimiter(
        patched,
        parameterOpen,
        '(',
        ')');
    if (parameterClose == NSNotFound) {
        if (error != nullptr) {
            *error = D16ShaderPatchError(
                @"D16 fragment entry point has an invalid parameter list");
        }
        return nil;
    }

    NSRange existingParameterRange = NSMakeRange(
        parameterOpen + 1,
        parameterClose - parameterOpen - 1);
    NSString *existingParameters = [patched
        substringWithRange:existingParameterRange];
    const BOOL hasExistingParameters =
        [existingParameters
            stringByTrimmingCharactersInSet:
                [NSCharacterSet whitespaceAndNewlineCharacterSet]].length != 0;
    NSRegularExpression *positionExpression =
        [NSRegularExpression
            regularExpressionWithPattern:
                @"\\b(?:const\\s+)?(?:float4|half4)\\s+"
                 "([A-Za-z_][A-Za-z0-9_]*)\\s*"
                 "\\[\\[\\s*position(?:\\s*,[^\\]]*)?\\s*\\]\\]"
            options:0
            error:error];
    if (positionExpression == nil) {
        return nil;
    }
    NSTextCheckingResult *positionMatch = [positionExpression
        firstMatchInString:patched
        options:0
        range:existingParameterRange];
    NSString *rasterPositionName = @"sol_metal_d16_position";
    if (positionMatch != nil) {
        rasterPositionName = [patched substringWithRange:
            [positionMatch rangeAtIndex:1]];
    } else {
        [patched insertString:
            hasExistingParameters
                ? @", float4 sol_metal_d16_position [[position]]"
                : @"float4 sol_metal_d16_position [[position]]"
                      atIndex:parameterClose];
    }

    const bool voidReturn = [returnType isEqualToString:@"void"];
    NSString *syntheticReturnType = nil;
    NSString *syntheticReturnValue = @"sol_metal_d16_output";
    if (voidReturn) {
        syntheticReturnType = [NSString stringWithFormat:
            @"SolMetalD16RasterDepthOutput_%@",
            functionName];
        const NSRange returnTypeRange = [functionMatch rangeAtIndex:1];
        [patched
            replaceCharactersInRange:returnTypeRange
            withString:syntheticReturnType];
        NSString *declaration = [NSString stringWithFormat:
            @"struct %@ {\n"
             "    float sol_metal_d16_depth [[depth(any)]];\n"
             "};\n\n",
            syntheticReturnType];
        [patched insertString:declaration atIndex:functionMatch.range.location];
        returnType = syntheticReturnType;
    } else {
        NSString *escapedReturnType =
            [NSRegularExpression escapedPatternForString:returnType];
        NSString *structPattern = [NSString stringWithFormat:
            @"\\bstruct\\s+%@\\b",
            escapedReturnType];
        NSRegularExpression *structExpression =
            [NSRegularExpression
                regularExpressionWithPattern:structPattern
                options:0
                error:error];
        NSTextCheckingResult *structMatch = [structExpression
            firstMatchInString:patched
            options:0
            range:NSMakeRange(0, patched.length)];
        if (structMatch == nil) {
            if (error != nullptr) {
                *error = D16ShaderPatchError([NSString stringWithFormat:
                    @"D16 fragment return type %@ is not a declared struct",
                    returnType]);
            }
            return nil;
        }
        NSRange structOpeningBrace = [patched
            rangeOfString:@"{"
            options:0
            range:NSMakeRange(
                NSMaxRange(structMatch.range),
                patched.length - NSMaxRange(structMatch.range))];
        if (structOpeningBrace.location == NSNotFound) {
            if (error != nullptr) {
                *error = D16ShaderPatchError(
                    @"D16 fragment return struct has no body");
            }
            return nil;
        }
        [patched insertString:
            @"\n    float sol_metal_d16_depth [[depth(any)]];"
            atIndex:structOpeningBrace.location + 1];
    }

    NSRegularExpression *functionAfterPatch =
        [NSRegularExpression regularExpressionWithPattern:functionPattern
                                                   options:0
                                                     error:error];
    NSTextCheckingResult *patchedFunctionMatch = [functionAfterPatch
        firstMatchInString:patched
        options:0
        range:NSMakeRange(0, patched.length)];
    if (patchedFunctionMatch == nil) {
        return nil;
    }
    const NSUInteger patchedParameterOpen =
        NSMaxRange(patchedFunctionMatch.range) - 1;
    const NSUInteger patchedParameterClose = ShaderMatchingDelimiter(
        patched,
        patchedParameterOpen,
        '(',
        ')');
    const NSUInteger functionOpeningBrace = patchedParameterClose == NSNotFound
        ? NSNotFound
        : ShaderNextCodeCharacter(patched, patchedParameterClose + 1, '{');
    if (functionOpeningBrace == NSNotFound) {
        if (error != nullptr) {
            *error = D16ShaderPatchError(
                @"D16 fragment entry point has no function body");
        }
        return nil;
    }
    NSUInteger functionClosingBrace = ShaderMatchingDelimiter(
        patched,
        functionOpeningBrace,
        '{',
        '}');
    if (functionClosingBrace == NSNotFound) {
        if (error != nullptr) {
            *error = D16ShaderPatchError(
                @"D16 fragment entry point has an unterminated body");
        }
        return nil;
    }
    NSRange bodyRange = NSMakeRange(
        functionOpeningBrace + 1,
        functionClosingBrace - functionOpeningBrace - 1);
    if (voidReturn) {
        NSString *const returnReplacement = [NSString stringWithFormat:
            @"return %@;",
            syntheticReturnValue];
        const std::vector<NSRange> bareReturns = ShaderBareReturnRanges(
            patched,
            bodyRange);
        NSUInteger returnExpansion = 0;
        for (auto iterator = bareReturns.rbegin();
             iterator != bareReturns.rend();
             ++iterator) {
            [patched
                replaceCharactersInRange:*iterator
                withString:returnReplacement];
            returnExpansion += returnReplacement.length - iterator->length;
        }
        functionClosingBrace += returnExpansion;

        NSString *initialization = [NSString stringWithFormat:
            @"\n    %@ %@ = {};\n"
             "    const float sol_metal_d16_depth_value = "
             "clamp(%@.z, 0.0f, 1.0f);\n"
             "    %@.sol_metal_d16_depth = "
             "rint(sol_metal_d16_depth_value * 65535.0f) "
             "* (1.0f / 65535.0f);\n",
            syntheticReturnType,
            syntheticReturnValue,
            rasterPositionName,
            syntheticReturnValue];
        [patched insertString:initialization atIndex:functionOpeningBrace + 1];
        functionClosingBrace += initialization.length;
        NSString *fallthroughReturn = [NSString stringWithFormat:
            @"\n    return %@;\n",
            syntheticReturnValue];
        [patched insertString:fallthroughReturn atIndex:functionClosingBrace];
        return patched;
    }

    NSRegularExpression *returnExpression =
        [NSRegularExpression
            regularExpressionWithPattern:
                @"\\breturn\\s+([A-Za-z_][A-Za-z0-9_]*)\\s*;"
            options:0
            error:error];
    NSArray<NSTextCheckingResult *> *returnMatches = [returnExpression
        matchesInString:patched
        options:0
        range:bodyRange];
    NSTextCheckingResult *returnMatch = returnMatches.lastObject;
    if (returnMatch == nil) {
        if (error != nullptr) {
            *error = D16ShaderPatchError(
                @"D16 fragment entry point has no value return");
        }
        return nil;
    }
    NSString *returnValue = [patched substringWithRange:
        [returnMatch rangeAtIndex:1]];
    NSString *quantization = [NSString stringWithFormat:
        @"    const float sol_metal_d16_depth_value = "
         "clamp(%@.z, 0.0f, 1.0f);\n"
         "    %@.sol_metal_d16_depth = "
         "rint(sol_metal_d16_depth_value * 65535.0f) "
         "* (1.0f / 65535.0f);\n",
        rasterPositionName,
        returnValue];
    [patched insertString:quantization atIndex:returnMatch.range.location];
    return patched;
}

static SolMetalStatus ValidateD16RasterDepthSourceRewrite(
    SolMetalContextObject *context,
    SolMetalValidationReport *report) {
    static NSString *const source = @R"msl(
#include <metal_stdlib>
using namespace metal;

struct SolD16RewriteOutput {
    float4 color [[color(0)]];
};

[[  early_fragment_tests  ]] fragment SolD16RewriteOutput sol_d16_rewrite(
    float4 existingPosition [[position]],
    constant uint &value [[buffer(0)]]) {
    SolD16RewriteOutput output;
    output.color = float4(float(value));
    return output;
}
)msl";
    static NSString *const explicitDepthSource = @R"msl(
#include <metal_stdlib>
using namespace metal;

struct SolD16ExplicitDepthOutput {
    float depth [[  depth ( greater )  ]];
};

fragment SolD16ExplicitDepthOutput sol_d16_explicit_depth() {
    SolD16ExplicitDepthOutput output;
    output.depth = 0.25f;
    return output;
}
)msl";
    static NSString *const emptyParameterSource = @R"msl(
#include <metal_stdlib>
using namespace metal;

struct SolD16EmptyParameterOutput {
    float4 color [[color(0)]];
};

fragment SolD16EmptyParameterOutput sol_d16_empty_parameters() {
    SolD16EmptyParameterOutput output;
    output.color = float4(1.0f);
    return output;
}
)msl";
    static NSString *const voidReturnSource = @R"msl(
#include <metal_stdlib>
using namespace metal;

struct SolD16VoidVertexOutput {
    float4 position [[position]];
};

vertex SolD16VoidVertexOutput sol_d16_void_vertex(
    uint vertexID [[vertex_id]]) {
    const float2 positions[3] = {
        float2(-1.0f, -1.0f),
        float2( 3.0f, -1.0f),
        float2(-1.0f,  3.0f),
    };
    SolD16VoidVertexOutput output;
    output.position = float4(positions[vertexID], 0.5f, 1.0f);
    return output;
}

fragment void sol_d16_void_fragment(
    device atomic_uint *counter [[buffer(0)]],
    bool frontFacing [[front_facing]],
    uint sampleID [[sample_id]]) {
    // return; remains a comment and must not be rewritten.
    if (!frontFacing) {
        return;
    }
    if (sampleID == 31u) {
        discard_fragment();
    }
    atomic_fetch_add_explicit(counter, 1u, memory_order_relaxed);
}
)msl";
    NSError *error = nil;
    NSString *rewritten = D16RasterDepthFragmentSource(
        source,
        @"sol_d16_rewrite",
        &error);
    const bool validRewrite =
        rewritten != nil &&
        [rewritten containsString:
            @"float sol_metal_d16_depth [[depth(any)]]"] &&
        [rewritten containsString:@"clamp(existingPosition.z"] &&
        [rewritten rangeOfString:@"early_fragment_tests"].location ==
            NSNotFound &&
        [rewritten rangeOfString:@"sol_metal_d16_position"].location ==
            NSNotFound;
    NSString *explicitDepthRewrite = D16RasterDepthFragmentSource(
        explicitDepthSource,
        @"sol_d16_explicit_depth",
        &error);
    const bool validExplicitDepthRewrite =
        explicitDepthRewrite != nil &&
        [explicitDepthRewrite containsString:@"[[depth(any)]]"] &&
        [explicitDepthRewrite rangeOfString:@"depth ( greater )"].location ==
            NSNotFound &&
        [explicitDepthRewrite containsString:
            @"sol_metal_d16_quantized_depth"];
    NSString *emptyParameterRewrite = D16RasterDepthFragmentSource(
        emptyParameterSource,
        @"sol_d16_empty_parameters",
        &error);
    const bool validEmptyParameterRewrite =
        emptyParameterRewrite != nil &&
        [emptyParameterRewrite containsString:
            @"sol_d16_empty_parameters(float4 sol_metal_d16_position [[position]])"] &&
        [emptyParameterRewrite rangeOfString:
            @"sol_d16_empty_parameters(, "].location == NSNotFound;
    NSString *voidReturnRewrite = D16RasterDepthFragmentSource(
        voidReturnSource,
        @"sol_d16_void_fragment",
        &error);
    static NSString *const voidReturnStatement =
        @"return sol_metal_d16_output;";
    const NSUInteger voidReturnCount = voidReturnRewrite == nil
        ? 0
        : [[voidReturnRewrite
            componentsSeparatedByString:voidReturnStatement] count] - 1;
    const NSRange firstVoidReturn = [voidReturnRewrite
        rangeOfString:voidReturnStatement];
    const NSRange discardCall = [voidReturnRewrite
        rangeOfString:@"discard_fragment();"];
    const NSRange storageWrite = [voidReturnRewrite
        rangeOfString:@"atomic_fetch_add_explicit(counter"];
    const NSRange finalVoidReturn = [voidReturnRewrite
        rangeOfString:voidReturnStatement
        options:NSBackwardsSearch];
    const bool validVoidReturnRewrite =
        voidReturnRewrite != nil &&
        [voidReturnRewrite containsString:
            @"struct SolMetalD16RasterDepthOutput_sol_d16_void_fragment"] &&
        [voidReturnRewrite containsString:
            @"float sol_metal_d16_depth [[depth(any)]]"] &&
        [voidReturnRewrite containsString:
            @"float4 sol_metal_d16_position [[position]]"] &&
        [voidReturnRewrite containsString:
            @"clamp(sol_metal_d16_position.z"] &&
        [voidReturnRewrite rangeOfString:
            @"fragment void sol_d16_void_fragment"].location == NSNotFound &&
        [voidReturnRewrite containsString:
            @"// return; remains a comment and must not be rewritten."] &&
        voidReturnCount == 2 &&
        firstVoidReturn.location != NSNotFound &&
        discardCall.location != NSNotFound &&
        storageWrite.location != NSNotFound &&
        finalVoidReturn.location != NSNotFound &&
        firstVoidReturn.location < discardCall.location &&
        discardCall.location < storageWrite.location &&
        storageWrite.location < finalVoidReturn.location;
    if (!validRewrite || !validExplicitDepthRewrite ||
        !validEmptyParameterRewrite || !validVoidReturnRewrite) {
        SetReportError(
            report,
            SOL_METAL_STATUS_VALIDATION_FAILED,
            error.localizedDescription ?:
                @"D16 raster-depth source rewrite changed its shader contract");
        return SOL_METAL_STATUS_VALIDATION_FAILED;
    }

    error = nil;
    BOOL cacheHit = NO;
    id<MTLLibrary> voidReturnLibrary = [context
        libraryWithSource:voidReturnRewrite
        fpFastMathFlags:spv::FPFastMathModeMaskNone
        preserveInvariance:NO
        cacheHit:&cacheHit
        error:&error];
    id<MTLFunction> voidReturnVertex = [voidReturnLibrary
        newFunctionWithName:@"sol_d16_void_vertex"];
    id<MTLFunction> voidReturnFragment = [voidReturnLibrary
        newFunctionWithName:@"sol_d16_void_fragment"];
    MTLRenderPipelineDescriptor *voidReturnDescriptor =
        [[MTLRenderPipelineDescriptor alloc] init];
    voidReturnDescriptor.label = @"SolMetal D16 Depth-Only Void Rewrite";
    voidReturnDescriptor.vertexFunction = voidReturnVertex;
    voidReturnDescriptor.fragmentFunction = voidReturnFragment;
    voidReturnDescriptor.depthAttachmentPixelFormat =
        MTLPixelFormatDepth32Float;
    id<MTLRenderPipelineState> voidReturnPipeline =
        voidReturnVertex == nil || voidReturnFragment == nil
            ? nil
            : [context.device
                newRenderPipelineStateWithDescriptor:voidReturnDescriptor
                error:&error];
    if (voidReturnLibrary == nil || voidReturnVertex == nil ||
        voidReturnFragment == nil || voidReturnPipeline == nil) {
        SetReportError(
            report,
            SOL_METAL_STATUS_SHADER_COMPILATION_FAILED,
            error.localizedDescription ?:
                @"D16 depth-only void fragment rewrite did not compile");
        return SOL_METAL_STATUS_SHADER_COMPILATION_FAILED;
    }
    return SOL_METAL_STATUS_OK;
}

static id<MTLFunction> D16RasterDepthFragmentFunction(
    SolMetalContextObject *context,
    SolMetalShaderTranslationObject *translation,
    NSError **error) {
    NSString *source = D16RasterDepthFragmentSource(
        translation.mslSource,
        translation.functionName,
        error);
    if (source == nil) {
        return nil;
    }
    BOOL cacheHit = NO;
    id<MTLLibrary> library = [context
        libraryWithSource:source
        fpFastMathFlags:spv::FPFastMathModeMaskNone
        preserveInvariance:translation.preserveInvariance
        cacheHit:&cacheHit
        error:error];
    if (library == nil) {
        return nil;
    }
    id<MTLFunction> function = [library
        newFunctionWithName:translation.functionName];
    if (function == nil && error != nullptr) {
        *error = D16ShaderPatchError([NSString stringWithFormat:
            @"D16 fragment entry point %@ was unavailable after compilation",
            translation.functionName]);
    }
    return function;
}

