@implementation SolMetalRenderPipelineObject

- (nullable instancetype)initWithDevice:(id<MTLDevice>)device
                                pipeline:(id<MTLRenderPipelineState>)pipeline
                         vertexFunction:(id<MTLFunction>)vertexFunction
                       fragmentFunction:(id<MTLFunction>)fragmentFunction
             colorAttachmentDescriptors:(NSData *)colorAttachmentDescriptors
      depthStencilFormat:(SolMetalTexturePixelFormat)depthStencilFormat
            depthStencilState:(nullable id<MTLDepthStencilState>)depthStencilState
                     hasStencil:(BOOL)hasStencil
           usesNativeD16Sidecar:(BOOL)usesNativeD16Sidecar
             usesLayeredRendering:(BOOL)usesLayeredRendering
          inputPrimitiveTopology:(SolMetalPrimitiveTopologyClass)inputPrimitiveTopology
             requiredVertexBufferIndices:(NSIndexSet *)requiredVertexBufferIndices
                     vertexBufferLayouts:(NSData *)vertexBufferLayouts
                        vertexAttributes:(NSData *)vertexAttributes
                    vertexShaderBindings:(NSArray<id<MTLBinding>> *)vertexShaderBindings
                  fragmentShaderBindings:(NSArray<id<MTLBinding>> *)fragmentShaderBindings {
    self = [super init];
    if (self == nil || device == nil || pipeline == nil ||
        vertexFunction == nil || fragmentFunction == nil ||
        colorAttachmentDescriptors == nil ||
        colorAttachmentDescriptors.length %
                sizeof(SolMetalRenderColorAttachmentDescriptor) !=
            0 ||
        (depthStencilFormat != 0 && depthStencilState == nil) ||
        requiredVertexBufferIndices == nil || vertexBufferLayouts == nil ||
        vertexAttributes == nil ||
        vertexAttributes.length % sizeof(SolMetalVertexAttribute) != 0 ||
        vertexShaderBindings == nil || fragmentShaderBindings == nil) {
        return nil;
    }
    _device = device;
    _pipeline = pipeline;
    _vertexFunction = vertexFunction;
    _fragmentFunction = fragmentFunction;
    _colorAttachmentDescriptors = [colorAttachmentDescriptors copy];
    if (_colorAttachmentDescriptors.length == 0) {
        _colorFormat = static_cast<SolMetalTexturePixelFormat>(0);
        _colorAttachmentIndex = 0;
    } else {
        const auto *firstColor =
            static_cast<const SolMetalRenderColorAttachmentDescriptor *>(
                _colorAttachmentDescriptors.bytes);
        _colorFormat = firstColor->pixel_format;
        _colorAttachmentIndex = firstColor->attachment_index;
    }
    _depthStencilFormat = depthStencilFormat;
    _depthStencilState = depthStencilState;
    _hasStencil = hasStencil;
    _usesNativeD16Sidecar = usesNativeD16Sidecar;
    _usesLayeredRendering = usesLayeredRendering;
    _inputPrimitiveTopology = inputPrimitiveTopology;
    _requiredVertexBufferIndices = [requiredVertexBufferIndices copy];
    _vertexBufferLayouts = [vertexBufferLayouts copy];
    _vertexAttributes = [vertexAttributes copy];
    _vertexShaderBindings = [vertexShaderBindings copy];
    _fragmentShaderBindings = [fragmentShaderBindings copy];
    _vertexArgumentBufferEncodeCount = 0;
    _fragmentArgumentBufferEncodeCount = 0;
    return self;
}

@end

@interface SolMetalVisibilityQueryObject : NSObject

@property(nonatomic, strong, readonly) id<MTLDevice> device;
@property(nonatomic, strong, readonly) NSLock *lock;
@property(nonatomic, strong, readonly)
    NSMutableArray<id<MTLBuffer>> *resultBuffers;
@property(nonatomic, assign) NSUInteger resultCount;

- (nullable instancetype)initWithDevice:(id<MTLDevice>)device;
- (BOOL)reserveResultBuffer:(id<MTLBuffer> _Nullable * _Nonnull)buffer
                     offset:(NSUInteger *)offset;
- (uint64_t)resolvedSampleCount;

@end

@implementation SolMetalVisibilityQueryObject

static constexpr NSUInteger SolMetalVisibilityResultsPerBuffer = 8'192;
static constexpr NSUInteger SolMetalVisibilityMaximumResults = 8'388'608;

- (nullable instancetype)initWithDevice:(id<MTLDevice>)device {
    self = [super init];
    if (self == nil || device == nil) {
        return nil;
    }
    _device = device;
    _lock = [[NSLock alloc] init];
    _resultBuffers = [[NSMutableArray alloc] init];
    _resultCount = 0;
    if (_lock == nil || _resultBuffers == nil) {
        return nil;
    }
    return self;
}

- (BOOL)reserveResultBuffer:(id<MTLBuffer> _Nullable * _Nonnull)buffer
                     offset:(NSUInteger *)offset {
    if (buffer == nullptr || offset == nullptr) {
        return NO;
    }
    *buffer = nil;
    *offset = 0;

    [_lock lock];
    @try {
        if (_resultCount >= SolMetalVisibilityMaximumResults) {
            return NO;
        }
        const NSUInteger bufferIndex =
            _resultCount / SolMetalVisibilityResultsPerBuffer;
        const NSUInteger resultIndex =
            _resultCount % SolMetalVisibilityResultsPerBuffer;
        if (bufferIndex == _resultBuffers.count) {
            id<MTLBuffer> resultBuffer = [_device
                newBufferWithLength:
                    SolMetalVisibilityResultsPerBuffer * sizeof(uint64_t)
                options:MTLResourceStorageModeShared];
            if (resultBuffer == nil || resultBuffer.contents == nullptr) {
                return NO;
            }
            std::memset(
                resultBuffer.contents,
                0,
                SolMetalVisibilityResultsPerBuffer * sizeof(uint64_t));
            [_resultBuffers addObject:resultBuffer];
        }
        *buffer = _resultBuffers[bufferIndex];
        *offset = resultIndex * sizeof(uint64_t);
        _resultCount += 1;
        return YES;
    } @finally {
        [_lock unlock];
    }
}

- (uint64_t)resolvedSampleCount {
    [_lock lock];
    @try {
        uint64_t total = 0;
        NSUInteger remaining = _resultCount;
        for (id<MTLBuffer> buffer in _resultBuffers) {
            const NSUInteger count = std::min(
                remaining,
                SolMetalVisibilityResultsPerBuffer);
            const auto *values = static_cast<const uint64_t *>(
                buffer.contents);
            if (values == nullptr) {
                return 0;
            }
            for (NSUInteger index = 0; index < count; ++index) {
                const uint64_t value = values[index];
                total = value > std::numeric_limits<uint64_t>::max() - total
                    ? std::numeric_limits<uint64_t>::max()
                    : total + value;
            }
            remaining -= count;
            if (remaining == 0) {
                break;
            }
        }
        return total;
    } @finally {
        [_lock unlock];
    }
}

@end

