static bool BufferRangeFits(
    SolMetalBufferObject *buffer,
    uint64_t offset,
    uint64_t size) {
    return buffer != nil && offset <= buffer.size && size <= buffer.size - offset;
}

static bool BufferBelongsToContext(
    SolMetalBufferObject *buffer,
    SolMetalContextObject *context) {
    return buffer != nil && context != nil && buffer.device == context.device &&
        buffer.ownerQueue == context.commandQueue;
}

