static bool SamplerFilterValue(
    SolMetalSamplerFilter filter,
    MTLSamplerMinMagFilter *metalFilter) {
    if (metalFilter == nullptr) {
        return false;
    }
    switch (filter) {
        case SOL_METAL_SAMPLER_FILTER_NEAREST:
            *metalFilter = MTLSamplerMinMagFilterNearest;
            return true;
        case SOL_METAL_SAMPLER_FILTER_LINEAR:
            *metalFilter = MTLSamplerMinMagFilterLinear;
            return true;
    }
    return false;
}

static bool SamplerMipFilterValue(
    SolMetalSamplerMipFilter filter,
    MTLSamplerMipFilter *metalFilter) {
    if (metalFilter == nullptr) {
        return false;
    }
    switch (filter) {
        case SOL_METAL_SAMPLER_MIP_FILTER_NOT_MIPMAPPED:
            *metalFilter = MTLSamplerMipFilterNotMipmapped;
            return true;
        case SOL_METAL_SAMPLER_MIP_FILTER_NEAREST:
            *metalFilter = MTLSamplerMipFilterNearest;
            return true;
        case SOL_METAL_SAMPLER_MIP_FILTER_LINEAR:
            *metalFilter = MTLSamplerMipFilterLinear;
            return true;
    }
    return false;
}

static bool SamplerAddressModeValue(
    SolMetalSamplerAddressMode mode,
    MTLSamplerAddressMode *metalMode) {
    if (metalMode == nullptr) {
        return false;
    }
    switch (mode) {
        case SOL_METAL_SAMPLER_ADDRESS_CLAMP_TO_EDGE:
            *metalMode = MTLSamplerAddressModeClampToEdge;
            return true;
        case SOL_METAL_SAMPLER_ADDRESS_REPEAT:
            *metalMode = MTLSamplerAddressModeRepeat;
            return true;
        case SOL_METAL_SAMPLER_ADDRESS_MIRROR_REPEAT:
            *metalMode = MTLSamplerAddressModeMirrorRepeat;
            return true;
        case SOL_METAL_SAMPLER_ADDRESS_CLAMP_TO_ZERO:
            *metalMode = MTLSamplerAddressModeClampToZero;
            return true;
        case SOL_METAL_SAMPLER_ADDRESS_CLAMP_TO_BORDER:
            *metalMode = MTLSamplerAddressModeClampToBorderColor;
            return true;
    }
    return false;
}

static bool SamplerBorderColorValue(
    SolMetalSamplerBorderColor color,
    MTLSamplerBorderColor *metalColor) {
    if (metalColor == nullptr) {
        return false;
    }
    switch (color) {
        case SOL_METAL_SAMPLER_BORDER_TRANSPARENT_BLACK:
            *metalColor = MTLSamplerBorderColorTransparentBlack;
            return true;
        case SOL_METAL_SAMPLER_BORDER_OPAQUE_BLACK:
            *metalColor = MTLSamplerBorderColorOpaqueBlack;
            return true;
        case SOL_METAL_SAMPLER_BORDER_OPAQUE_WHITE:
            *metalColor = MTLSamplerBorderColorOpaqueWhite;
            return true;
    }
    return false;
}

static bool ColorWriteMaskValue(
    uint32_t mask,
    MTLColorWriteMask *metalMask) {
    if (metalMask == nullptr || (mask & ~SOL_METAL_COLOR_WRITE_ALL) != 0) {
        return false;
    }
    MTLColorWriteMask value = MTLColorWriteMaskNone;
    if ((mask & SOL_METAL_COLOR_WRITE_RED) != 0) {
        value |= MTLColorWriteMaskRed;
    }
    if ((mask & SOL_METAL_COLOR_WRITE_GREEN) != 0) {
        value |= MTLColorWriteMaskGreen;
    }
    if ((mask & SOL_METAL_COLOR_WRITE_BLUE) != 0) {
        value |= MTLColorWriteMaskBlue;
    }
    if ((mask & SOL_METAL_COLOR_WRITE_ALPHA) != 0) {
        value |= MTLColorWriteMaskAlpha;
    }
    *metalMask = value;
    return true;
}

static bool PrimitiveTypeValue(
    SolMetalPrimitiveType primitive,
    MTLPrimitiveType *metalPrimitive) {
