static SolMetalVertexFormat DropLastVertexFormatComponent(
    SolMetalVertexFormat format) {
    switch (format) {
        case SOL_METAL_VERTEX_FORMAT_FLOAT4:
            return SOL_METAL_VERTEX_FORMAT_FLOAT3;
        case SOL_METAL_VERTEX_FORMAT_FLOAT3:
            return SOL_METAL_VERTEX_FORMAT_FLOAT2;
        case SOL_METAL_VERTEX_FORMAT_FLOAT2:
            return SOL_METAL_VERTEX_FORMAT_FLOAT;
        case SOL_METAL_VERTEX_FORMAT_HALF4:
            return SOL_METAL_VERTEX_FORMAT_HALF3;
        case SOL_METAL_VERTEX_FORMAT_HALF3:
            return SOL_METAL_VERTEX_FORMAT_HALF2;
        case SOL_METAL_VERTEX_FORMAT_HALF2:
            return SOL_METAL_VERTEX_FORMAT_HALF;
        case SOL_METAL_VERTEX_FORMAT_UCHAR4_NORMALIZED:
            return SOL_METAL_VERTEX_FORMAT_UCHAR3_NORMALIZED;
        case SOL_METAL_VERTEX_FORMAT_UCHAR3_NORMALIZED:
            return SOL_METAL_VERTEX_FORMAT_UCHAR2_NORMALIZED;
        case SOL_METAL_VERTEX_FORMAT_UCHAR2_NORMALIZED:
            return SOL_METAL_VERTEX_FORMAT_UCHAR_NORMALIZED;
        case SOL_METAL_VERTEX_FORMAT_CHAR4_NORMALIZED:
            return SOL_METAL_VERTEX_FORMAT_CHAR3_NORMALIZED;
        case SOL_METAL_VERTEX_FORMAT_CHAR3_NORMALIZED:
            return SOL_METAL_VERTEX_FORMAT_CHAR2_NORMALIZED;
        case SOL_METAL_VERTEX_FORMAT_CHAR2_NORMALIZED:
            return SOL_METAL_VERTEX_FORMAT_CHAR_NORMALIZED;
        case SOL_METAL_VERTEX_FORMAT_USHORT4_NORMALIZED:
            return SOL_METAL_VERTEX_FORMAT_USHORT3_NORMALIZED;
        case SOL_METAL_VERTEX_FORMAT_USHORT3_NORMALIZED:
            return SOL_METAL_VERTEX_FORMAT_USHORT2_NORMALIZED;
        case SOL_METAL_VERTEX_FORMAT_USHORT2_NORMALIZED:
            return SOL_METAL_VERTEX_FORMAT_USHORT_NORMALIZED;
        case SOL_METAL_VERTEX_FORMAT_SHORT4_NORMALIZED:
            return SOL_METAL_VERTEX_FORMAT_SHORT3_NORMALIZED;
        case SOL_METAL_VERTEX_FORMAT_SHORT3_NORMALIZED:
            return SOL_METAL_VERTEX_FORMAT_SHORT2_NORMALIZED;
        case SOL_METAL_VERTEX_FORMAT_SHORT2_NORMALIZED:
            return SOL_METAL_VERTEX_FORMAT_SHORT_NORMALIZED;
        case SOL_METAL_VERTEX_FORMAT_UCHAR4:
            return SOL_METAL_VERTEX_FORMAT_UCHAR3;
        case SOL_METAL_VERTEX_FORMAT_UCHAR3:
            return SOL_METAL_VERTEX_FORMAT_UCHAR2;
        case SOL_METAL_VERTEX_FORMAT_UCHAR2:
            return SOL_METAL_VERTEX_FORMAT_UCHAR;
        case SOL_METAL_VERTEX_FORMAT_CHAR4:
            return SOL_METAL_VERTEX_FORMAT_CHAR3;
        case SOL_METAL_VERTEX_FORMAT_CHAR3:
            return SOL_METAL_VERTEX_FORMAT_CHAR2;
        case SOL_METAL_VERTEX_FORMAT_CHAR2:
            return SOL_METAL_VERTEX_FORMAT_CHAR;
        case SOL_METAL_VERTEX_FORMAT_USHORT4:
            return SOL_METAL_VERTEX_FORMAT_USHORT3;
        case SOL_METAL_VERTEX_FORMAT_USHORT3:
            return SOL_METAL_VERTEX_FORMAT_USHORT2;
        case SOL_METAL_VERTEX_FORMAT_USHORT2:
            return SOL_METAL_VERTEX_FORMAT_USHORT;
        case SOL_METAL_VERTEX_FORMAT_SHORT4:
            return SOL_METAL_VERTEX_FORMAT_SHORT3;
        case SOL_METAL_VERTEX_FORMAT_SHORT3:
            return SOL_METAL_VERTEX_FORMAT_SHORT2;
        case SOL_METAL_VERTEX_FORMAT_SHORT2:
            return SOL_METAL_VERTEX_FORMAT_SHORT;
        case SOL_METAL_VERTEX_FORMAT_UINT4:
            return SOL_METAL_VERTEX_FORMAT_UINT3;
        case SOL_METAL_VERTEX_FORMAT_UINT3:
            return SOL_METAL_VERTEX_FORMAT_UINT2;
        case SOL_METAL_VERTEX_FORMAT_UINT2:
            return SOL_METAL_VERTEX_FORMAT_UINT;
        case SOL_METAL_VERTEX_FORMAT_INT4:
            return SOL_METAL_VERTEX_FORMAT_INT3;
        case SOL_METAL_VERTEX_FORMAT_INT3:
            return SOL_METAL_VERTEX_FORMAT_INT2;
        case SOL_METAL_VERTEX_FORMAT_INT2:
            return SOL_METAL_VERTEX_FORMAT_INT;
        default:
            return format;
    }
}

static SolMetalVertexFormat VertexFormatFittingStride(
    SolMetalVertexFormat format,
    uint32_t offset,
    uint32_t stride) {
    SolMetalVertexFormat candidate = format;
    MTLVertexFormat ignoredMetalFormat = MTLVertexFormatInvalid;
    uint32_t byteSize = 0;
    while (VertexFormatProperties(
               candidate,
               &ignoredMetalFormat,
               &byteSize) &&
           static_cast<uint64_t>(offset) + byteSize > stride) {
        const SolMetalVertexFormat reduced =
            DropLastVertexFormatComponent(candidate);
        if (reduced == candidate) {
            return format;
        }
        candidate = reduced;
    }
    return candidate;
}

