    switch (stepFunction) {
        case SOL_METAL_VERTEX_STEP_PER_VERTEX:
            *metalStepFunction = MTLVertexStepFunctionPerVertex;
            return true;
        case SOL_METAL_VERTEX_STEP_PER_INSTANCE:
            *metalStepFunction = MTLVertexStepFunctionPerInstance;
            return true;
        case SOL_METAL_VERTEX_STEP_CONSTANT:
            *metalStepFunction = MTLVertexStepFunctionConstant;
            return true;
    }
    return false;
}

static bool IndexTypeProperties(
    SolMetalIndexType indexType,
    MTLIndexType *metalIndexType,
    uint32_t *byteSize) {
    if (metalIndexType == nullptr || byteSize == nullptr) {
        return false;
    }
    switch (indexType) {
        case SOL_METAL_INDEX_UINT8:
            // The render path expands the byte stream into a temporary UInt16
            // buffer before issuing the indexed draw.
            *metalIndexType = MTLIndexTypeUInt16;
            *byteSize = 1;
            return true;
        case SOL_METAL_INDEX_UINT16:
            *metalIndexType = MTLIndexTypeUInt16;
            *byteSize = 2;
            return true;
        case SOL_METAL_INDEX_UINT32:
            *metalIndexType = MTLIndexTypeUInt32;
            *byteSize = 4;
            return true;
    }
    return false;
}

