        preserveInvariance:NO
        cacheHit:&cacheHit
        error:&error];
    BOOL tagWriterCacheHit = NO;
    id<MTLLibrary> tagWriterLibrary = [context
        libraryWithSource:tagWriterSource
        fpFastMathFlags:spv::FPFastMathModeMaskNone
