        error:&error];
    BOOL tagReplayCacheHit = NO;
    id<MTLLibrary> tagReplayLibrary = [context
        libraryWithSource:tagReplaySource
        fpFastMathFlags:spv::FPFastMathModeMaskNone
        preserveInvariance:YES
        cacheHit:&tagReplayCacheHit
        error:&error];
    id<MTLFunction> vertex = [library
        newFunctionWithName:@"sol_d16_guard_vertex"];
    if (library == nil || tagWriterLibrary == nil ||
        tagReplayLibrary == nil || vertex == nil) {
        SetReportError(
            report,
            SOL_METAL_STATUS_SHADER_COMPILATION_FAILED,
            error.localizedDescription ?:
                @"D16 late-depth guard fixture did not compile");
        return SOL_METAL_STATUS_SHADER_COMPILATION_FAILED;
    }

    const auto CreateTranslation = [&](NSString *functionName,
                                       BOOL mayTerminateInvocation) {
        id<MTLFunction> function = [library
            newFunctionWithName:functionName];
        return [[SolMetalShaderTranslationObject alloc]
            initWithDevice:context.device
            mslSource:source
            library:library
            function:function
            stage:SOL_METAL_SHADER_STAGE_FRAGMENT
            fpFastMathFlags:spv::FPFastMathModeMaskNone
            preserveInvariance:NO
            requestsEarlyFragmentTests:YES
            mayTerminateInvocation:mayTerminateInvocation
            functionName:functionName];
    };
    SolMetalShaderTranslationObject *vertexTranslation =
        [[SolMetalShaderTranslationObject alloc]
            initWithDevice:context.device
            mslSource:source
            library:library
            function:vertex
            stage:SOL_METAL_SHADER_STAGE_VERTEX
            fpFastMathFlags:spv::FPFastMathModeMaskNone
            preserveInvariance:NO
            requestsEarlyFragmentTests:NO
            mayTerminateInvocation:NO
            functionName:@"sol_d16_guard_vertex"];
    id<MTLFunction> occludedVertex = [library
        newFunctionWithName:@"sol_d16_guard_occluded_vertex"];
    SolMetalShaderTranslationObject *occludedVertexTranslation =
        [[SolMetalShaderTranslationObject alloc]
            initWithDevice:context.device
            mslSource:source
            library:library
            function:occludedVertex
            stage:SOL_METAL_SHADER_STAGE_VERTEX
            fpFastMathFlags:spv::FPFastMathModeMaskNone
            preserveInvariance:NO
            requestsEarlyFragmentTests:NO
            mayTerminateInvocation:NO
            functionName:@"sol_d16_guard_occluded_vertex"];
    id<MTLFunction> prepassFunction = [library
        newFunctionWithName:@"sol_d16_guard_prepass"];
    SolMetalShaderTranslationObject *prepassTranslation =
        [[SolMetalShaderTranslationObject alloc]
            initWithDevice:context.device
            mslSource:source
            library:library
            function:prepassFunction
            stage:SOL_METAL_SHADER_STAGE_FRAGMENT
            fpFastMathFlags:spv::FPFastMathModeMaskNone
            preserveInvariance:NO
            requestsEarlyFragmentTests:NO
            mayTerminateInvocation:NO
            functionName:@"sol_d16_guard_prepass"];
    SolMetalShaderTranslationObject *readTranslation =
        CreateTranslation(@"sol_d16_guard_read", NO);
    SolMetalShaderTranslationObject *writeTranslation =
        CreateTranslation(@"sol_d16_guard_write", NO);
    SolMetalShaderTranslationObject *discardTranslation =
        CreateTranslation(@"sol_d16_guard_discard", YES);
    SolMetalShaderTranslationObject *writeDiscardTranslation =
        CreateTranslation(@"sol_d16_guard_write_discard", YES);
    id<MTLFunction> tagWriterVertex = [tagWriterLibrary
        newFunctionWithName:@"sol_d16_tag_writer_vertex"];
    id<MTLFunction> tagWriterFragment = [tagWriterLibrary
        newFunctionWithName:@"sol_d16_tag_writer_fragment"];
    id<MTLFunction> tagReplayVertex = [tagReplayLibrary
        newFunctionWithName:@"sol_d16_tag_replay_vertex"];
    id<MTLFunction> tagReplayFragment = [tagReplayLibrary
        newFunctionWithName:@"sol_d16_tag_replay_fragment"];
    SolMetalShaderTranslationObject *tagWriterVertexTranslation =
        [[SolMetalShaderTranslationObject alloc]
            initWithDevice:context.device
            mslSource:tagWriterSource
            library:tagWriterLibrary
            function:tagWriterVertex
            stage:SOL_METAL_SHADER_STAGE_VERTEX
            fpFastMathFlags:spv::FPFastMathModeMaskNone
            preserveInvariance:NO
            requestsEarlyFragmentTests:NO
            mayTerminateInvocation:NO
            functionName:@"sol_d16_tag_writer_vertex"];
    SolMetalShaderTranslationObject *tagWriterFragmentTranslation =
        [[SolMetalShaderTranslationObject alloc]
            initWithDevice:context.device
            mslSource:tagWriterSource
            library:tagWriterLibrary
            function:tagWriterFragment
            stage:SOL_METAL_SHADER_STAGE_FRAGMENT
            fpFastMathFlags:spv::FPFastMathModeMaskNone
            preserveInvariance:NO
            requestsEarlyFragmentTests:NO
            mayTerminateInvocation:NO
            functionName:@"sol_d16_tag_writer_fragment"];
    SolMetalShaderTranslationObject *tagReplayVertexTranslation =
        [[SolMetalShaderTranslationObject alloc]
            initWithDevice:context.device
            mslSource:tagReplaySource
            library:tagReplayLibrary
            function:tagReplayVertex
            stage:SOL_METAL_SHADER_STAGE_VERTEX
            fpFastMathFlags:spv::FPFastMathModeMaskNone
            preserveInvariance:YES
            requestsEarlyFragmentTests:NO
            mayTerminateInvocation:NO
            functionName:@"sol_d16_tag_replay_vertex"];
    SolMetalShaderTranslationObject *tagReplayFragmentTranslation =
        [[SolMetalShaderTranslationObject alloc]
            initWithDevice:context.device
            mslSource:tagReplaySource
            library:tagReplayLibrary
            function:tagReplayFragment
            stage:SOL_METAL_SHADER_STAGE_FRAGMENT
            fpFastMathFlags:spv::FPFastMathModeMaskNone
            preserveInvariance:YES
            requestsEarlyFragmentTests:YES
            mayTerminateInvocation:YES
            functionName:@"sol_d16_tag_replay_fragment"];
    if (vertexTranslation == nil || occludedVertexTranslation == nil ||
        prepassTranslation == nil || readTranslation == nil ||
        writeTranslation == nil || discardTranslation == nil ||
        writeDiscardTranslation == nil ||
        tagWriterVertexTranslation == nil ||
        tagWriterFragmentTranslation == nil ||
        tagReplayVertexTranslation == nil ||
        tagReplayFragmentTranslation == nil) {
        SetReportError(
            report,
            SOL_METAL_STATUS_ALLOCATION_FAILED,
            @"D16 late-depth guard translations were unavailable");
        return SOL_METAL_STATUS_ALLOCATION_FAILED;
    }

    const auto CreatePipeline = [&](SolMetalShaderTranslationObject *fragment,
                                    SolMetalRenderPipelineRef *pipeline) {
        SolMetalRenderPipelineAdvancedDescriptor descriptor = {};
        descriptor.struct_size = sizeof(descriptor);
        descriptor.abi_version = SOL_METAL_ABI_VERSION;
        descriptor.vertex_translation = (__bridge void *)vertexTranslation;
        descriptor.fragment_translation = (__bridge void *)fragment;
        descriptor.color_format = SOL_METAL_TEXTURE_FORMAT_BGRA8_UNORM;
        descriptor.color_write_mask = SOL_METAL_COLOR_WRITE_ALL;
        descriptor.depth_stencil_format =
            SOL_METAL_TEXTURE_FORMAT_DEPTH16_UNORM;
        descriptor.depth_stencil.depth_compare_function =
            SOL_METAL_COMPARE_EQUAL;
        return sol_metal_context_render_pipeline_create_advanced(
            (__bridge void *)context,
            &descriptor,
            nullptr,
            0,
            nullptr,
            0,
            pipeline);
    };
    SolMetalRenderPipelineRef readPipeline = nullptr;
    SolMetalRenderPipelineRef writePipeline = nullptr;
    SolMetalRenderPipelineRef discardPipeline = nullptr;
    SolMetalRenderPipelineRef writeDiscardPipeline = nullptr;
    const SolMetalStatus readStatus = CreatePipeline(
        readTranslation,
        &readPipeline);
    const SolMetalStatus writeStatus = CreatePipeline(
        writeTranslation,
        &writePipeline);
    const SolMetalStatus discardStatus = CreatePipeline(
        discardTranslation,
        &discardPipeline);
    const SolMetalStatus writeDiscardStatus = CreatePipeline(
        writeDiscardTranslation,
        &writeDiscardPipeline);
    const bool validGuard =
        readStatus == SOL_METAL_STATUS_OK && readPipeline != nullptr &&
        writeStatus == SOL_METAL_STATUS_OK && writePipeline != nullptr &&
        discardStatus == SOL_METAL_STATUS_OK && discardPipeline != nullptr &&
        writeDiscardStatus == SOL_METAL_STATUS_OK &&
        writeDiscardPipeline != nullptr;
    sol_metal_render_pipeline_destroy(readPipeline);
    sol_metal_render_pipeline_destroy(writePipeline);
    sol_metal_render_pipeline_destroy(discardPipeline);
    sol_metal_render_pipeline_destroy(writeDiscardPipeline);
    if (!validGuard) {
        SetReportError(
            report,
            SOL_METAL_STATUS_VALIDATION_FAILED,
            [NSString stringWithFormat:
                @"D16 early-test preservation returned read=%d write=%d discard=%d write-discard=%d",
                readStatus,
                writeStatus,
                discardStatus,
                writeDiscardStatus]);
        return SOL_METAL_STATUS_VALIDATION_FAILED;
    }

    const SolMetalContextRef contextRef = (__bridge void *)context;
    SolMetalRenderPipelineRef semanticPrepassPipeline = nullptr;
    SolMetalRenderPipelineRef semanticReplayPipeline = nullptr;
    SolMetalRenderPipelineRef semanticOccludedPipeline = nullptr;
    SolMetalRenderPipelineRef semanticTagWriterPipeline = nullptr;
    SolMetalRenderPipelineRef semanticTagReplayPipeline = nullptr;
    SolMetalBufferRef semanticCounterBuffer = nullptr;
    SolMetalBufferRef semanticTagBuffer = nullptr;
    SolMetalTextureRef semanticColorTarget = nullptr;
    SolMetalTextureRef semanticDepthTarget = nullptr;
    const auto CleanupSemanticResources = [&]() {
        sol_metal_render_pipeline_destroy(semanticPrepassPipeline);
        sol_metal_render_pipeline_destroy(semanticReplayPipeline);
        sol_metal_render_pipeline_destroy(semanticOccludedPipeline);
        sol_metal_render_pipeline_destroy(semanticTagWriterPipeline);
        sol_metal_render_pipeline_destroy(semanticTagReplayPipeline);
        sol_metal_buffer_destroy(semanticCounterBuffer);
        sol_metal_buffer_destroy(semanticTagBuffer);
        sol_metal_texture_destroy(semanticColorTarget);
        sol_metal_texture_destroy(semanticDepthTarget);
    };
    const auto FailSemanticValidation = [&](
        SolMetalStatus failureStatus,
        NSString *message) {
        CleanupSemanticResources();
        SetReportError(report, failureStatus, message);
        return failureStatus;
    };
    const auto CreateSemanticPipeline = [&](
        SolMetalShaderTranslationObject *semanticVertex,
        SolMetalShaderTranslationObject *semanticFragment,
        SolMetalCompareFunction depthCompare,
        uint32_t depthWriteEnabled,
        uint32_t colorWriteMask,
        SolMetalRenderPipelineRef *pipeline) {
        SolMetalRenderPipelineAdvancedDescriptor descriptor = {};
        descriptor.struct_size = sizeof(descriptor);
        descriptor.abi_version = SOL_METAL_ABI_VERSION;
        descriptor.vertex_translation = (__bridge void *)semanticVertex;
        descriptor.fragment_translation = (__bridge void *)semanticFragment;
        descriptor.color_format = SOL_METAL_TEXTURE_FORMAT_BGRA8_UNORM;
        descriptor.color_write_mask = colorWriteMask;
        descriptor.depth_stencil_format =
            SOL_METAL_TEXTURE_FORMAT_DEPTH16_UNORM;
        descriptor.depth_stencil.depth_compare_function = depthCompare;
        descriptor.depth_stencil.depth_write_enabled = depthWriteEnabled;
        return sol_metal_context_render_pipeline_create_advanced(
            contextRef,
            &descriptor,
            nullptr,
            0,
            nullptr,
            0,
            pipeline);
    };

    SolMetalStatus semanticStatus = CreateSemanticPipeline(
        vertexTranslation,
        prepassTranslation,
        SOL_METAL_COMPARE_ALWAYS,
        1,
        0,
        &semanticPrepassPipeline);
    if (semanticStatus == SOL_METAL_STATUS_OK) {
        semanticStatus = CreateSemanticPipeline(
            vertexTranslation,
            writeDiscardTranslation,
            SOL_METAL_COMPARE_EQUAL,
            0,
            SOL_METAL_COLOR_WRITE_ALL,
            &semanticReplayPipeline);
    }
    if (semanticStatus == SOL_METAL_STATUS_OK) {
        semanticStatus = CreateSemanticPipeline(
            occludedVertexTranslation,
            writeDiscardTranslation,
            SOL_METAL_COMPARE_EQUAL,
            0,
            SOL_METAL_COLOR_WRITE_ALL,
            &semanticOccludedPipeline);
    }
    if (semanticStatus == SOL_METAL_STATUS_OK) {
        semanticStatus = CreateSemanticPipeline(
            tagWriterVertexTranslation,
            tagWriterFragmentTranslation,
            SOL_METAL_COMPARE_ALWAYS,
            1,
            0,
            &semanticTagWriterPipeline);
    }
    if (semanticStatus == SOL_METAL_STATUS_OK) {
        semanticStatus = CreateSemanticPipeline(
            tagReplayVertexTranslation,
            tagReplayFragmentTranslation,
            SOL_METAL_COMPARE_EQUAL,
            0,
            SOL_METAL_COLOR_WRITE_ALL,
            &semanticTagReplayPipeline);
    }
    if (semanticStatus != SOL_METAL_STATUS_OK ||
        semanticPrepassPipeline == nullptr ||
        semanticReplayPipeline == nullptr ||
        semanticOccludedPipeline == nullptr ||
        semanticTagWriterPipeline == nullptr ||
        semanticTagReplayPipeline == nullptr) {
        const SolMetalStatus failureStatus =
            semanticStatus == SOL_METAL_STATUS_OK
                ? SOL_METAL_STATUS_VALIDATION_FAILED
                : semanticStatus;
        return FailSemanticValidation(
            failureStatus,
            @"D16 semantic early-test pipelines could not be created");
    }

    SolMetalBufferDescriptor counterDescriptor = {};
    counterDescriptor.struct_size = sizeof(counterDescriptor);
    counterDescriptor.abi_version = SOL_METAL_ABI_VERSION;
    counterDescriptor.size = sizeof(uint32_t);
    counterDescriptor.storage_mode = SOL_METAL_BUFFER_STORAGE_PRIVATE;
    semanticStatus = sol_metal_context_buffer_create(
        contextRef,
        &counterDescriptor,
        &semanticCounterBuffer);
    if (semanticStatus == SOL_METAL_STATUS_OK) {
        semanticStatus = sol_metal_context_buffer_create(
            contextRef,
            &counterDescriptor,
            &semanticTagBuffer);
    }
    uint32_t zeroCounter = 0;
    if (semanticStatus == SOL_METAL_STATUS_OK) {
        semanticStatus = sol_metal_context_buffer_upload(
            contextRef,
            semanticCounterBuffer,
            0,
            &zeroCounter,
            sizeof(zeroCounter));
    }

    constexpr uint32_t SemanticWidth = 64;
    constexpr uint32_t SemanticHeight = 64;
    constexpr uint64_t SemanticBytesPerRow = SemanticWidth * 4;
    constexpr uint64_t SemanticByteCount =
        SemanticBytesPerRow * SemanticHeight;
    SolMetalTextureDescriptor semanticTextureDescriptor = {};
    semanticTextureDescriptor.struct_size = sizeof(semanticTextureDescriptor);
    semanticTextureDescriptor.abi_version = SOL_METAL_ABI_VERSION;
    semanticTextureDescriptor.width = SemanticWidth;
    semanticTextureDescriptor.height = SemanticHeight;
    semanticTextureDescriptor.pixel_format =
        SOL_METAL_TEXTURE_FORMAT_BGRA8_UNORM;
    semanticTextureDescriptor.storage_mode =
        SOL_METAL_BUFFER_STORAGE_PRIVATE;
    semanticTextureDescriptor.usage = SOL_METAL_TEXTURE_USAGE_RENDER_TARGET;
    if (semanticStatus == SOL_METAL_STATUS_OK) {
        semanticStatus = sol_metal_context_texture_create_2d(
            contextRef,
            &semanticTextureDescriptor,
            &semanticColorTarget);
    }
    semanticTextureDescriptor.pixel_format =
        SOL_METAL_TEXTURE_FORMAT_DEPTH16_UNORM;
    if (semanticStatus == SOL_METAL_STATUS_OK) {
        semanticStatus = sol_metal_context_texture_create_2d(
            contextRef,
            &semanticTextureDescriptor,
            &semanticDepthTarget);
    }
    if (semanticStatus != SOL_METAL_STATUS_OK ||
        semanticCounterBuffer == nullptr || semanticTagBuffer == nullptr ||
        semanticColorTarget == nullptr ||
        semanticDepthTarget == nullptr) {
        const SolMetalStatus failureStatus =
            semanticStatus == SOL_METAL_STATUS_OK
                ? SOL_METAL_STATUS_VALIDATION_FAILED
                : semanticStatus;
        return FailSemanticValidation(
            failureStatus,
            @"D16 semantic early-test resources could not be created");
    }

    SolMetalBufferBinding counterBinding = {};
    counterBinding.index = 0;
    counterBinding.buffer = semanticCounterBuffer;
    SolMetalRenderStageBindings semanticFragmentBindings = {};
    semanticFragmentBindings.struct_size =
        sizeof(semanticFragmentBindings);
    semanticFragmentBindings.abi_version = SOL_METAL_ABI_VERSION;
    semanticFragmentBindings.buffer_binding_count = 1;
    semanticFragmentBindings.buffer_bindings = &counterBinding;

    SolMetalBufferBinding tagBinding = {};
    tagBinding.index = 0;
    tagBinding.buffer = semanticTagBuffer;
    SolMetalRenderStageBindings semanticTagBindings = {};
    semanticTagBindings.struct_size = sizeof(semanticTagBindings);
    semanticTagBindings.abi_version = SOL_METAL_ABI_VERSION;
    semanticTagBindings.buffer_binding_count = 1;
    semanticTagBindings.buffer_bindings = &tagBinding;

    SolMetalRenderDrawDescriptor semanticDraw = {};
    semanticDraw.struct_size = sizeof(semanticDraw);
    semanticDraw.abi_version = SOL_METAL_ABI_VERSION;
    semanticDraw.color_target = semanticColorTarget;
    semanticDraw.primitive_type = SOL_METAL_PRIMITIVE_TRIANGLE;
    semanticDraw.load_action = SOL_METAL_RENDER_LOAD_CLEAR;
    semanticDraw.store_action = SOL_METAL_RENDER_STORE;
    semanticDraw.vertex_count = 3;
    semanticDraw.instance_count = 1;
    semanticDraw.clear_alpha = 1.0;
    semanticDraw.viewport_width = SemanticWidth;
    semanticDraw.viewport_height = SemanticHeight;
    semanticDraw.viewport_far_z = 1.0;
    semanticDraw.scissor_width = SemanticWidth;
    semanticDraw.scissor_height = SemanticHeight;

    SolMetalRenderPassState semanticPass = {};
    semanticPass.struct_size = sizeof(semanticPass);
    semanticPass.abi_version = SOL_METAL_ABI_VERSION;
    semanticPass.depth_stencil_target = semanticDepthTarget;
    semanticPass.depth_load_action = SOL_METAL_RENDER_LOAD_CLEAR;
    semanticPass.depth_store_action = SOL_METAL_RENDER_STORE;
    semanticPass.clear_depth = 1.0;

    semanticStatus = sol_metal_context_render_draw_advanced(
        contextRef,
        semanticPrepassPipeline,
        &semanticDraw,
        nullptr,
        nullptr,
        nullptr,
        &semanticPass);
    semanticDraw.load_action = SOL_METAL_RENDER_LOAD;
    semanticPass.depth_load_action = SOL_METAL_RENDER_LOAD;
    if (semanticStatus == SOL_METAL_STATUS_OK) {
        semanticStatus = sol_metal_context_render_draw_advanced(
            contextRef,
            semanticReplayPipeline,
            &semanticDraw,
            nullptr,
            nullptr,
            &semanticFragmentBindings,
            &semanticPass);
    }

    std::vector<uint8_t> semanticPixels(SemanticByteCount, 0xcd);
    uint32_t replayStorageCount = 0;
    if (semanticStatus == SOL_METAL_STATUS_OK) {
        semanticStatus = sol_metal_context_texture_download_2d(
            contextRef,
            semanticColorTarget,
            semanticPixels.data(),
            SemanticBytesPerRow,
            semanticPixels.size());
    }
    if (semanticStatus == SOL_METAL_STATUS_OK) {
        semanticStatus = sol_metal_context_buffer_download(
            contextRef,
            semanticCounterBuffer,
            0,
            &replayStorageCount,
            sizeof(replayStorageCount));
    }

    uint64_t matchingGreenPixels = 0;
    uint64_t matchingBlackPixels = 0;
    uint64_t unexpectedPixels = 0;
    if (semanticStatus == SOL_METAL_STATUS_OK) {
        for (uint32_t y = 0; y < SemanticHeight; ++y) {
            for (uint32_t x = 0; x < SemanticWidth; ++x) {
                const size_t offset =
                    (static_cast<size_t>(y) * SemanticWidth + x) * 4;
                const bool isGreen =
                    semanticPixels[offset + 0] <= 8 &&
                    semanticPixels[offset + 1] >= 240 &&
                    semanticPixels[offset + 2] <= 8 &&
                    semanticPixels[offset + 3] >= 240;
                const bool isBlack =
                    semanticPixels[offset + 0] <= 8 &&
                    semanticPixels[offset + 1] <= 8 &&
                    semanticPixels[offset + 2] <= 8 &&
                    semanticPixels[offset + 3] >= 240;
                if (x < SemanticWidth / 2 && isGreen) {
                    matchingGreenPixels += 1;
                } else if (x >= SemanticWidth / 2 && isBlack) {
                    matchingBlackPixels += 1;
                } else {
                    unexpectedPixels += 1;
                }
            }
        }
    }

    if (semanticStatus == SOL_METAL_STATUS_OK) {
        semanticStatus = sol_metal_context_buffer_upload(
            contextRef,
            semanticCounterBuffer,
            0,
            &zeroCounter,
            sizeof(zeroCounter));
    }
    if (semanticStatus == SOL_METAL_STATUS_OK) {
        semanticStatus = sol_metal_context_render_draw_advanced(
            contextRef,
            semanticOccludedPipeline,
            &semanticDraw,
            nullptr,
            nullptr,
            &semanticFragmentBindings,
            &semanticPass);
    }
    uint32_t occludedStorageCount = 0;
    if (semanticStatus == SOL_METAL_STATUS_OK) {
        semanticStatus = sol_metal_context_buffer_download(
            contextRef,
            semanticCounterBuffer,
            0,
            &occludedStorageCount,
            sizeof(occludedStorageCount));
    }
    if (semanticStatus != SOL_METAL_STATUS_OK) {
        return FailSemanticValidation(
            semanticStatus,
            @"D16 semantic early-test draw or readback failed");
    }

    constexpr uint64_t ExpectedHalfCoverage =
        static_cast<uint64_t>(SemanticWidth / 2) * SemanticHeight;
    const bool replayMatched =
        matchingGreenPixels == ExpectedHalfCoverage &&
        matchingBlackPixels == ExpectedHalfCoverage &&
        unexpectedPixels == 0 &&
        replayStorageCount == ExpectedHalfCoverage;
    const bool earlyRejectionPreserved = occludedStorageCount == 0;
    if (!replayMatched || !earlyRejectionPreserved) {
        return FailSemanticValidation(
            SOL_METAL_STATUS_VALIDATION_FAILED,
            [NSString stringWithFormat:
                @"D16 semantic replay expected green=%llu black=%llu storage=%llu occluded-storage=0, got green=%llu black=%llu unexpected=%llu storage=%u occluded-storage=%u",
                static_cast<unsigned long long>(ExpectedHalfCoverage),
                static_cast<unsigned long long>(ExpectedHalfCoverage),
                static_cast<unsigned long long>(ExpectedHalfCoverage),
                static_cast<unsigned long long>(matchingGreenPixels),
                static_cast<unsigned long long>(matchingBlackPixels),
                static_cast<unsigned long long>(unexpectedPixels),
                replayStorageCount,
                occludedStorageCount]);
    }

    // These are the two raw TOTK tags from the cave pass whose nibble-swapped
    // depths land exactly halfway between adjacent D16 values. The explicit
    // fragment writer runs against the D32 backing; the early-test replay must
    // then survive the D32 -> native-D16 sidecar conversion with Equal depth.
    constexpr uint32_t HalfTieTags[] = {35u, 32u};
    for (const uint32_t rawTag : HalfTieTags) {
        semanticStatus = sol_metal_context_buffer_upload(
            contextRef,
            semanticTagBuffer,
            0,
            &rawTag,
            sizeof(rawTag));
        if (semanticStatus == SOL_METAL_STATUS_OK) {
            semanticStatus = sol_metal_context_buffer_upload(
                contextRef,
                semanticCounterBuffer,
                0,
                &zeroCounter,
                sizeof(zeroCounter));
        }

        semanticDraw.load_action = SOL_METAL_RENDER_LOAD_CLEAR;
        semanticPass.depth_load_action = SOL_METAL_RENDER_LOAD_CLEAR;
        semanticPass.clear_depth = 1.0;
        if (semanticStatus == SOL_METAL_STATUS_OK) {
            semanticStatus = sol_metal_context_render_draw_advanced(
                contextRef,
                semanticTagWriterPipeline,
                &semanticDraw,
                nullptr,
                nullptr,
                &semanticTagBindings,
                &semanticPass);
        }
        semanticDraw.load_action = SOL_METAL_RENDER_LOAD;
        semanticPass.depth_load_action = SOL_METAL_RENDER_LOAD;
        if (semanticStatus == SOL_METAL_STATUS_OK) {
            semanticStatus = sol_metal_context_render_draw_advanced(
                contextRef,
                semanticTagReplayPipeline,
                &semanticDraw,
                nullptr,
                &semanticTagBindings,
                &semanticFragmentBindings,
                &semanticPass);
        }

        std::fill(semanticPixels.begin(), semanticPixels.end(), 0xcd);
        uint32_t tagStorageCount = 0;
        if (semanticStatus == SOL_METAL_STATUS_OK) {
            semanticStatus = sol_metal_context_texture_download_2d(
                contextRef,
                semanticColorTarget,
                semanticPixels.data(),
                SemanticBytesPerRow,
                semanticPixels.size());
        }
        if (semanticStatus == SOL_METAL_STATUS_OK) {
            semanticStatus = sol_metal_context_buffer_download(
                contextRef,
                semanticCounterBuffer,
                0,
                &tagStorageCount,
                sizeof(tagStorageCount));
        }
        if (semanticStatus != SOL_METAL_STATUS_OK) {
            return FailSemanticValidation(
                semanticStatus,
                [NSString stringWithFormat:
                    @"D16 half-tie tag %u writer, sidecar, or early replay failed",
                    rawTag]);
        }

        uint64_t tagGreenPixels = 0;
        uint64_t tagBlackPixels = 0;
        uint64_t tagUnexpectedPixels = 0;
        for (uint32_t y = 0; y < SemanticHeight; ++y) {
            for (uint32_t x = 0; x < SemanticWidth; ++x) {
                const size_t offset =
                    (static_cast<size_t>(y) * SemanticWidth + x) * 4;
                const bool isGreen =
                    semanticPixels[offset + 0] <= 8 &&
                    semanticPixels[offset + 1] >= 240 &&
                    semanticPixels[offset + 2] <= 8 &&
                    semanticPixels[offset + 3] >= 240;
                const bool isBlack =
                    semanticPixels[offset + 0] <= 8 &&
                    semanticPixels[offset + 1] <= 8 &&
                    semanticPixels[offset + 2] <= 8 &&
                    semanticPixels[offset + 3] >= 240;
                if (x < SemanticWidth / 2 && isGreen) {
                    tagGreenPixels += 1;
                } else if (x >= SemanticWidth / 2 && isBlack) {
                    tagBlackPixels += 1;
                } else {
                    tagUnexpectedPixels += 1;
                }
            }
        }
        if (tagGreenPixels != ExpectedHalfCoverage ||
            tagBlackPixels != ExpectedHalfCoverage ||
            tagUnexpectedPixels != 0 ||
            tagStorageCount != ExpectedHalfCoverage) {
            return FailSemanticValidation(
                SOL_METAL_STATUS_VALIDATION_FAILED,
                [NSString stringWithFormat:
                    @"D16 half-tie tag %u expected green=%llu black=%llu storage=%llu, got green=%llu black=%llu unexpected=%llu storage=%u",
                    rawTag,
                    static_cast<unsigned long long>(ExpectedHalfCoverage),
                    static_cast<unsigned long long>(ExpectedHalfCoverage),
                    static_cast<unsigned long long>(ExpectedHalfCoverage),
                    static_cast<unsigned long long>(tagGreenPixels),
                    static_cast<unsigned long long>(tagBlackPixels),
                    static_cast<unsigned long long>(tagUnexpectedPixels),
                    tagStorageCount]);
        }
        report->bytes_verified += SemanticByteCount +
            sizeof(tagStorageCount);
        report->output_signature = HashBytes(
            &rawTag,
            sizeof(rawTag),
            report->output_signature);
        report->output_signature = HashBytes(
            semanticPixels.data(),
            semanticPixels.size(),
            report->output_signature);
        report->output_signature = HashBytes(
            &tagStorageCount,
            sizeof(tagStorageCount),
            report->output_signature);
    }

    report->bytes_verified += SemanticByteCount +
        sizeof(replayStorageCount) + sizeof(occludedStorageCount);
    report->output_signature = HashBytes(
        semanticPixels.data(),
        semanticPixels.size(),
        report->output_signature);
    report->output_signature = HashBytes(
        &replayStorageCount,
        sizeof(replayStorageCount),
        report->output_signature);
    report->output_signature = HashBytes(
        &occludedStorageCount,
        sizeof(occludedStorageCount),
        report->output_signature);
    CleanupSemanticResources();
    return SOL_METAL_STATUS_OK;
}

static bool TextureFormatProperties(
    SolMetalTexturePixelFormat format,
    MTLPixelFormat *metalFormat,
    uint32_t *bytesPerPixel) {
    if (metalFormat == nullptr || bytesPerPixel == nullptr) {
        return false;
    }
    switch (format) {
        case SOL_METAL_TEXTURE_FORMAT_RGBA8_UNORM:
            *metalFormat = MTLPixelFormatRGBA8Unorm;
            *bytesPerPixel = 4;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_BGRA8_UNORM:
            *metalFormat = MTLPixelFormatBGRA8Unorm;
            *bytesPerPixel = 4;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_R32_UINT:
            *metalFormat = MTLPixelFormatR32Uint;
            *bytesPerPixel = 4;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_RGBA16_FLOAT:
            *metalFormat = MTLPixelFormatRGBA16Float;
            *bytesPerPixel = 8;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_RGBA16_UINT:
            *metalFormat = MTLPixelFormatRGBA16Uint;
            *bytesPerPixel = 8;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_RGBA16_UNORM:
            *metalFormat = MTLPixelFormatRGBA16Unorm;
            *bytesPerPixel = 8;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_DEPTH32_FLOAT:
            *metalFormat = MTLPixelFormatDepth32Float;
            *bytesPerPixel = 4;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_DEPTH16_UNORM:
            *metalFormat = UseD32BackingForD16()
                ? MTLPixelFormatDepth32Float
                : MTLPixelFormatDepth16Unorm;
            // Preserve the guest-visible D16 layout. The opt-in D32 backing
            // path expands transfers explicitly instead of leaking Metal's
            // four-byte storage size into the Sol Engine ABI.
            *bytesPerPixel = 2;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_DEPTH32_FLOAT_STENCIL8:
            *metalFormat = MTLPixelFormatDepth32Float_Stencil8;
            *bytesPerPixel = 8;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_R8_UNORM:
            *metalFormat = MTLPixelFormatR8Unorm;
            *bytesPerPixel = 1;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_RG8_UNORM:
            *metalFormat = MTLPixelFormatRG8Unorm;
            *bytesPerPixel = 2;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_R16_UNORM:
            *metalFormat = MTLPixelFormatR16Unorm;
            *bytesPerPixel = 2;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_RG16_UNORM:
            *metalFormat = MTLPixelFormatRG16Unorm;
            *bytesPerPixel = 4;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_R16_FLOAT:
