            return true;
        case SOL_METAL_TEXTURE_FORMAT_R32_FLOAT:
            *metalFormat = MTLPixelFormatR32Float;
            *bytesPerPixel = 4;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_RG32_FLOAT:
