            return true;
        case SOL_METAL_TEXTURE_FORMAT_RGBA8_SRGB:
            *metalFormat = MTLPixelFormatRGBA8Unorm_sRGB;
            *bytesPerPixel = 4;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_BGRA8_SRGB:
            *metalFormat = MTLPixelFormatBGRA8Unorm_sRGB;
            *bytesPerPixel = 4;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_R32_SINT:
            *metalFormat = MTLPixelFormatR32Sint;
            *bytesPerPixel = 4;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_RG16_SNORM:
