            return true;
        case SOL_METAL_TEXTURE_FORMAT_D24_UNORM_STENCIL8:
            *metalFormat = MTLPixelFormatDepth32Float_Stencil8;
            *bytesPerPixel = 4;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_BC1_RGBA_UNORM:
            *metalFormat = MTLPixelFormatBC1_RGBA;
            *bytesPerPixel = 8;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_BC1_RGBA_SRGB:
            *metalFormat = MTLPixelFormatBC1_RGBA_sRGB;
            *bytesPerPixel = 8;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_BC2_RGBA_UNORM:
            *metalFormat = MTLPixelFormatBC2_RGBA;
            *bytesPerPixel = 16;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_BC2_RGBA_SRGB:
            *metalFormat = MTLPixelFormatBC2_RGBA_sRGB;
