            return true;
        case SOL_METAL_TEXTURE_FORMAT_BC4_R_UNORM:
            *metalFormat = MTLPixelFormatBC4_RUnorm;
            *bytesPerPixel = 8;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_BC4_R_SNORM:
            *metalFormat = MTLPixelFormatBC4_RSnorm;
            *bytesPerPixel = 8;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_BC5_RG_UNORM:
            *metalFormat = MTLPixelFormatBC5_RGUnorm;
            *bytesPerPixel = 16;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_BC5_RG_SNORM:
            *metalFormat = MTLPixelFormatBC5_RGSnorm;
            *bytesPerPixel = 16;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_BC6H_RGB_FLOAT:
            *metalFormat = MTLPixelFormatBC6H_RGBFloat;
            *bytesPerPixel = 16;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_BC6H_RGB_UFLOAT:
            *metalFormat = MTLPixelFormatBC6H_RGBUfloat;
            *bytesPerPixel = 16;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_BC7_RGBA_UNORM:
            *metalFormat = MTLPixelFormatBC7_RGBAUnorm;
            *bytesPerPixel = 16;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_BC7_RGBA_SRGB:
            *metalFormat = MTLPixelFormatBC7_RGBAUnorm_sRGB;
            *bytesPerPixel = 16;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_RGB10A2_UNORM:
            *metalFormat = MTLPixelFormatRGB10A2Unorm;
            *bytesPerPixel = 4;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_RGB10A2_UINT:
            *metalFormat = MTLPixelFormatRGB10A2Uint;
            *bytesPerPixel = 4;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_RGB9E5_FLOAT:
            *metalFormat = MTLPixelFormatRGB9E5Float;
            *bytesPerPixel = 4;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_BGR10A2_UNORM:
            *metalFormat = MTLPixelFormatBGR10A2Unorm;
            *bytesPerPixel = 4;
            return true;
        case SOL_METAL_TEXTURE_FORMAT_RGBA32_UINT:
            *metalFormat = MTLPixelFormatRGBA32Uint;
            *bytesPerPixel = 16;
            return true;
    }
    return false;
}

static SolMetalClearOutputType ClearOutputType(
    SolMetalTexturePixelFormat format) {
    switch (format) {
        case SOL_METAL_TEXTURE_FORMAT_R32_SINT:
            return SolMetalClearOutputSignedInteger;
        case SOL_METAL_TEXTURE_FORMAT_R32_UINT:
        case SOL_METAL_TEXTURE_FORMAT_R8_UINT:
        case SOL_METAL_TEXTURE_FORMAT_RGB10A2_UINT:
        case SOL_METAL_TEXTURE_FORMAT_RGBA32_UINT:
        case SOL_METAL_TEXTURE_FORMAT_RGBA16_UINT:
            return SolMetalClearOutputUnsignedInteger;
        default:
            return SolMetalClearOutputFloat;
    }
}

static bool ResolveTextureClearRegion(
    uint32_t flags,
    uint32_t allowedFlags,
    uint32_t x,
    uint32_t y,
    uint32_t width,
    uint32_t height,
    uint32_t targetWidth,
    uint32_t targetHeight,
    MTLScissorRect *region,
    bool *fullSurface) {
    if (region == nullptr || fullSurface == nullptr ||
        (flags & ~allowedFlags) != 0) {
        return false;
    }
    if ((flags & SOL_METAL_TEXTURE_CLEAR_REGION) == 0) {
        *region = MTLScissorRect{0, 0, targetWidth, targetHeight};
        *fullSurface = true;
        return true;
    }
    const uint64_t right = static_cast<uint64_t>(x) + width;
    const uint64_t bottom = static_cast<uint64_t>(y) + height;
    if (width == 0 || height == 0 || x >= targetWidth ||
        y >= targetHeight || right > targetWidth || bottom > targetHeight) {
        return false;
    }
    *region = MTLScissorRect{x, y, width, height};
    *fullSurface = x == 0 && y == 0 && width == targetWidth &&
        height == targetHeight;
    return true;
}

