static bool TextureTransferLayout(
    SolMetalTextureObject *texture,
    uint64_t callerBytesPerRow,
    uint64_t callerSize,
    NSUInteger *tightBytesPerRow,
    NSUInteger *stagingBytesPerRow,
    NSUInteger *stagingSize) {
    if (texture == nil || tightBytesPerRow == nullptr ||
        stagingBytesPerRow == nullptr || stagingSize == nullptr) {
        return false;
    }
    const uint64_t blockColumns =
        (static_cast<uint64_t>(texture.width) + texture.blockWidth - 1) /
        texture.blockWidth;
    const uint64_t blockRows =
        (static_cast<uint64_t>(texture.height) + texture.blockHeight - 1) /
        texture.blockHeight;
    const uint64_t tightRow = blockColumns * texture.bytesPerPixel;
    if (callerBytesPerRow < tightRow || texture.depthOrArrayLength == 0 ||
        blockRows > std::numeric_limits<uint64_t>::max() /
            callerBytesPerRow) {
        return false;
    }
    const uint64_t callerBytesPerImage =
        callerBytesPerRow * blockRows;
    if (texture.depthOrArrayLength >
            std::numeric_limits<uint64_t>::max() / callerBytesPerImage ||
        callerSize < callerBytesPerImage * texture.depthOrArrayLength) {
        return false;
    }

    // Metal's linear/texture-buffer alignment queries deliberately reject
    // depth/stencil formats. Buffer-to-private-texture blits still accept
    // depth data, using the platform's conservative 256-byte row alignment.
    const NSUInteger alignment =
        (IsDepthStencilFormat(texture.pixelFormat) ||
         IsBlockCompressedFormat(texture.pixelFormat))
        ? 256
        : std::max<NSUInteger>(
            1,
            [texture.device minimumTextureBufferAlignmentForPixelFormat:
                texture.texture.pixelFormat]);
    if (tightRow > std::numeric_limits<NSUInteger>::max() ||
        alignment > std::numeric_limits<NSUInteger>::max() - tightRow) {
        return false;
    }
    const NSUInteger tight = static_cast<NSUInteger>(tightRow);
    const NSUInteger aligned = ((tight + alignment - 1) / alignment) * alignment;
    if (blockRows > std::numeric_limits<NSUInteger>::max() / aligned) {
        return false;
    }
    *tightBytesPerRow = tight;
    *stagingBytesPerRow = aligned;
    *stagingSize = aligned * static_cast<NSUInteger>(blockRows);
    return true;
}

struct SolMetalMipTransferLayout {
    uint32_t width;
    uint32_t height;
    uint32_t depthOrSlices;
    uint32_t rowCount;
    NSUInteger tightBytesPerRow;
    NSUInteger sourceBytesPerRow;
    uint64_t sourceOffset;
    NSUInteger stagingBytesPerRow;
    NSUInteger stagingBytesPerImage;
    NSUInteger stagingOffset;
};

static bool BuildMipTransferLayouts(
    SolMetalTextureObject *texture,
    uint64_t levelZeroBytesPerRow,
    uint64_t callerSize,
    std::vector<SolMetalMipTransferLayout> *layouts,
    NSUInteger *totalStagingSize) {
    if (texture == nil || layouts == nullptr || totalStagingSize == nullptr ||
        texture.mipmapLevelCount == 0 ||
        texture.depthOrArrayLength == 0) {
        return false;
    }
    layouts->clear();
    layouts->reserve(texture.mipmapLevelCount);
    *totalStagingSize = 0;
    uint64_t sourceOffset = 0;
    const NSUInteger metalAlignment =
        (IsDepthStencilFormat(texture.pixelFormat) ||
         IsBlockCompressedFormat(texture.pixelFormat))
        ? 256
        : std::max<NSUInteger>(
            1,
            [texture.device minimumTextureBufferAlignmentForPixelFormat:
                texture.texture.pixelFormat]);
    for (uint32_t level = 0; level < texture.mipmapLevelCount; ++level) {
        const uint32_t width = std::max(1u, texture.width >> level);
        const uint32_t height = std::max(1u, texture.height >> level);
        const uint32_t depthOrSlices =
            texture.textureType == SOL_METAL_TEXTURE_TYPE_3D
            ? std::max(1u, texture.depthOrArrayLength >> level)
            : texture.depthOrArrayLength;
        const uint32_t blockColumns =
            (width + texture.blockWidth - 1) / texture.blockWidth;
        const uint32_t blockRows =
            (height + texture.blockHeight - 1) / texture.blockHeight;
        const uint64_t tightRow64 =
            static_cast<uint64_t>(blockColumns) * texture.bytesPerPixel;
        const uint64_t sourceRow64 = (tightRow64 + 3u) & ~uint64_t{3u};
        if ((level == 0 && levelZeroBytesPerRow != sourceRow64) ||
            tightRow64 > std::numeric_limits<NSUInteger>::max() ||
            sourceRow64 > std::numeric_limits<NSUInteger>::max() ||
            sourceRow64 > std::numeric_limits<uint64_t>::max() / blockRows) {
            return false;
        }
        const uint64_t sourceBytesPerImage64 = sourceRow64 * blockRows;
        if (depthOrSlices >
                std::numeric_limits<uint64_t>::max() /
                    sourceBytesPerImage64 ||
            sourceOffset > std::numeric_limits<uint64_t>::max() -
                sourceBytesPerImage64 * depthOrSlices) {
            return false;
        }
        const NSUInteger tightRow = static_cast<NSUInteger>(tightRow64);
        const NSUInteger sourceRow = static_cast<NSUInteger>(sourceRow64);
        if (metalAlignment >
            std::numeric_limits<NSUInteger>::max() - tightRow) {
            return false;
        }
        const NSUInteger stagingRow =
            ((tightRow + metalAlignment - 1) / metalAlignment) *
            metalAlignment;
        if (blockRows > std::numeric_limits<NSUInteger>::max() / stagingRow) {
            return false;
        }
        const NSUInteger stagingImage = stagingRow * blockRows;
        if (depthOrSlices >
                std::numeric_limits<NSUInteger>::max() / stagingImage ||
            *totalStagingSize > std::numeric_limits<NSUInteger>::max() -
                stagingImage * depthOrSlices) {
            return false;
        }
        layouts->push_back({
            width,
            height,
            depthOrSlices,
            blockRows,
            tightRow,
            sourceRow,
            sourceOffset,
            stagingRow,
            stagingImage,
            *totalStagingSize,
        });
        sourceOffset +=
            sourceBytesPerImage64 * depthOrSlices;
        *totalStagingSize +=
            stagingImage * depthOrSlices;
    }
    return callerSize >= sourceOffset;
}

static bool ShaderStageExecutionModel(
    SolMetalShaderStage stage,
    spv::ExecutionModel *executionModel) {
    if (executionModel == nullptr) {
        return false;
    }
    switch (stage) {
        case SOL_METAL_SHADER_STAGE_VERTEX:
            *executionModel = spv::ExecutionModelVertex;
            return true;
        case SOL_METAL_SHADER_STAGE_TESSELLATION_CONTROL:
            *executionModel = spv::ExecutionModelTessellationControl;
            return true;
        case SOL_METAL_SHADER_STAGE_TESSELLATION_EVALUATION:
            *executionModel = spv::ExecutionModelTessellationEvaluation;
            return true;
        case SOL_METAL_SHADER_STAGE_GEOMETRY:
            *executionModel = spv::ExecutionModelGeometry;
            return true;
        case SOL_METAL_SHADER_STAGE_FRAGMENT:
            *executionModel = spv::ExecutionModelFragment;
            return true;
        case SOL_METAL_SHADER_STAGE_COMPUTE:
            *executionModel = spv::ExecutionModelGLCompute;
            return true;
    }
    return false;
}

static bool IsInitialTranslationStage(SolMetalShaderStage stage) {
    return stage == SOL_METAL_SHADER_STAGE_VERTEX ||
        stage == SOL_METAL_SHADER_STAGE_FRAGMENT ||
        stage == SOL_METAL_SHADER_STAGE_COMPUTE;
}

static uint32_t SaturatingUInt32(size_t value) {
    return static_cast<uint32_t>(std::min<size_t>(
        value,
        std::numeric_limits<uint32_t>::max()));
}

static SolMetalStatus InitializeTranslationReport(
    SolMetalSpirvTranslationReport *report) {
    if (report == nullptr) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }
    if (report->struct_size < sizeof(SolMetalSpirvTranslationReport)) {
        return SOL_METAL_STATUS_INCOMPATIBLE_ABI;
    }
    std::memset(report, 0, sizeof(*report));
    report->struct_size = sizeof(*report);
    report->abi_version = SOL_METAL_ABI_VERSION;
    return SOL_METAL_STATUS_OK;
}

static SolMetalStatus TranslationFailure(
    SolMetalSpirvTranslationReport *report,
    SolMetalStatus status,
    NSString *message) {
    SetTranslationError(report, message);
    return status;
}

