SolMetalStatus sol_metal_context_visibility_query_create(
    SolMetalContextRef context,
    SolMetalVisibilityQueryRef *out_query) {
    if (out_query == nullptr) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }
    *out_query = nullptr;
    SolMetalContextObject *contextObject = ContextObject(context);
    if (contextObject == nil) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }
    @autoreleasepool {
        @try {
            SolMetalVisibilityQueryObject *query =
                [[SolMetalVisibilityQueryObject alloc]
                    initWithDevice:contextObject.device];
            if (query == nil) {
                return SOL_METAL_STATUS_ALLOCATION_FAILED;
            }
            *out_query = (__bridge_retained void *)query;
            return SOL_METAL_STATUS_OK;
        } @catch (NSException *exception) {
            [contextObject setLastErrorMessage:exception.reason ?:
                @"Metal visibility-query allocation failed"];
            return SOL_METAL_STATUS_INTERNAL_ERROR;
        }
    }
}

void sol_metal_visibility_query_destroy(SolMetalVisibilityQueryRef query) {
    if (query == nullptr) {
        return;
    }
    @autoreleasepool {
        CFBridgingRelease(query);
    }
}

SolMetalStatus sol_metal_context_visibility_query_resolve(
    SolMetalContextRef context,
    SolMetalVisibilityQueryRef query,
    uint64_t *out_visible_samples) {
    if (out_visible_samples == nullptr) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }
    *out_visible_samples = 0;
    SolMetalContextObject *contextObject = ContextObject(context);
    SolMetalVisibilityQueryObject *queryObject =
        VisibilityQueryObject(query);
    if (!VisibilityQueryBelongsToContext(queryObject, contextObject)) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }
    @autoreleasepool {
        @try {
            *out_visible_samples = [queryObject resolvedSampleCount];
            return SOL_METAL_STATUS_OK;
        } @catch (NSException *exception) {
            [contextObject setLastErrorMessage:exception.reason ?:
                @"Metal visibility-query resolution failed"];
            return SOL_METAL_STATUS_INTERNAL_ERROR;
        }
    }
}

