SolMetalStatus sol_metal_context_memory_barrier(
    SolMetalContextRef context) {
    SolMetalContextObject *object = ContextObject(context);
    if (object == nil) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }

    [object.runtimeBatchLock lock];
    @try {
        const SolMetalStatus status = [object beginRuntimeCommand];
        if (status != SOL_METAL_STATUS_OK) {
            return status;
        }
        // Metal tracks hazards between encoders on one command buffer. Ending
        // the render encoder provides the guest-visible memory dependency
        // without paying for an otherwise empty command-buffer submission.
        EndRuntimeDrawEncoderLocked(object);
        return SOL_METAL_STATUS_OK;
    } @catch (NSException *exception) {
        [object setLastErrorMessage:[NSString stringWithFormat:
            @"Metal memory-barrier exception: %@",
            exception.reason ?: exception.name]];
        return SOL_METAL_STATUS_INTERNAL_ERROR;
    } @finally {
        [object.runtimeBatchLock unlock];
    }
}

SolMetalStatus sol_metal_context_timeline_submit(
    SolMetalContextRef context,
    uint64_t *out_value) {
    if (out_value == nullptr) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }
    *out_value = 0;

    SolMetalContextObject *object = ContextObject(context);
    if (object == nil) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }

    @autoreleasepool {
        bool timelineLocked = false;
        bool batchLocked = false;
        uint64_t value = 0;
        @try {
            [object.runtimeBatchLock lock];
            batchLocked = true;
            const SolMetalStatus flushStatus = FlushRuntimeDrawBatchLocked(
                object,
                @"SolMetal Draw Batch Before Timeline",
                SOL_METAL_RUNTIME_BATCH_FLUSH_TIMELINE);
            if (flushStatus != SOL_METAL_STATUS_OK) {
                return flushStatus;
            }
            [object.timelineCondition lock];
            timelineLocked = true;
            if (object.timelineSubmittedValue ==
                std::numeric_limits<uint64_t>::max()) {
                return SOL_METAL_STATUS_UNSUPPORTED;
            }

            id<MTLCommandBuffer> commandBuffer =
                [object.commandQueue commandBuffer];
            if (commandBuffer == nil) {
                return SOL_METAL_STATUS_ALLOCATION_FAILED;
            }

            value = object.timelineSubmittedValue + 1;
            object.timelineSubmittedValue = value;
            commandBuffer.label = [NSString stringWithFormat:
                @"SolMetal Timeline %llu",
                static_cast<unsigned long long>(value)];

            // Metal command queues preserve commit order. Holding the timeline
            // condition through commit gives concurrent GAL callers one
            // unambiguous, monotonically increasing submission sequence.
            [commandBuffer addCompletedHandler:^(id<MTLCommandBuffer> completed) {
                SolMetalStatus completionStatus =
                    completed.status == MTLCommandBufferStatusCompleted
                    ? SOL_METAL_STATUS_OK
                    : SOL_METAL_STATUS_COMMAND_FAILED;
                [object.timelineCondition lock];
                object.timelineCompletedValue = std::max(
                    object.timelineCompletedValue,
                    value);
                if (completionStatus != SOL_METAL_STATUS_OK) {
                    if (object.timelineFirstFailedValue == 0) {
                        object.timelineFirstFailedValue = value;
                    }
                    object.timelineLastStatus = completionStatus;
                }
                [object.timelineCondition broadcast];
                [object.timelineCondition unlock];
            }];
            [commandBuffer commit];
            *out_value = value;
            return SOL_METAL_STATUS_OK;
        } @catch (NSException *) {
            if (value != 0) {
                object.timelineCompletedValue = std::max(
                    object.timelineCompletedValue,
                    value);
                if (object.timelineFirstFailedValue == 0) {
                    object.timelineFirstFailedValue = value;
                }
                object.timelineLastStatus = SOL_METAL_STATUS_INTERNAL_ERROR;
                [object.timelineCondition broadcast];
            }
            return SOL_METAL_STATUS_INTERNAL_ERROR;
        } @finally {
            if (timelineLocked) {
                [object.timelineCondition unlock];
            }
            if (batchLocked) {
                [object.runtimeBatchLock unlock];
            }
        }
    }
}

SolMetalStatus sol_metal_context_timeline_query(
    SolMetalContextRef context,
    SolMetalTimelineReport *report) {
    if (report == nullptr) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }
    if (report->struct_size < sizeof(SolMetalTimelineReport)) {
        return SOL_METAL_STATUS_INCOMPATIBLE_ABI;
    }

    SolMetalContextObject *object = ContextObject(context);
    if (object == nil) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }

    [object.timelineCondition lock];
    const uint64_t submitted = object.timelineSubmittedValue;
    const uint64_t completed = object.timelineCompletedValue;
    const uint64_t failed = object.timelineFirstFailedValue;
    const SolMetalStatus lastStatus = object.timelineLastStatus;
    [object.timelineCondition unlock];
    [object.runtimeBatchLock lock];
    const uint64_t batchedDrawCount = object.runtimeBatchedDrawCount;
    const uint64_t drawCommandBufferCount =
        object.runtimeDrawCommandBufferCount;
    const uint64_t drawBoundaryFlushCount =
        object.runtimeDrawBoundaryFlushCount;
    const uint64_t drawRenderPassCount = object.runtimeDrawRenderPassCount;
    const NSUInteger maximumDrawBatchSize =
        object.runtimeMaximumDrawBatchSize;
    const NSUInteger pendingDrawCount = object.runtimeDrawCount;
    [object.runtimeBatchLock unlock];

    std::memset(report, 0, sizeof(*report));
    report->struct_size = sizeof(*report);
    report->abi_version = SOL_METAL_ABI_VERSION;
    report->latest_submitted_value = submitted;
    report->latest_completed_value = completed;
    report->first_failed_value = failed;
    report->last_status = lastStatus;
    report->draw_render_pass_count = static_cast<uint32_t>(
        std::min<uint64_t>(
            drawRenderPassCount,
            std::numeric_limits<uint32_t>::max()));
    report->batched_draw_count = batchedDrawCount;
    report->draw_command_buffer_count = drawCommandBufferCount;
    report->draw_boundary_flush_count = drawBoundaryFlushCount;
    report->maximum_draw_batch_size = static_cast<uint32_t>(std::min<NSUInteger>(
        maximumDrawBatchSize,
        std::numeric_limits<uint32_t>::max()));
    report->pending_draw_count = static_cast<uint32_t>(std::min<NSUInteger>(
        pendingDrawCount,
        std::numeric_limits<uint32_t>::max()));
    return SOL_METAL_STATUS_OK;
}

SolMetalStatus sol_metal_context_runtime_batch_query(
    SolMetalContextRef context,
    SolMetalRuntimeBatchReport *report) {
    if (report == nullptr) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }
    if (report->struct_size < sizeof(SolMetalRuntimeBatchReport)) {
        return SOL_METAL_STATUS_INCOMPATIBLE_ABI;
    }
    SolMetalContextObject *object = ContextObject(context);
    if (object == nil) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }

    [object.runtimeBatchLock lock];
    std::memset(report, 0, sizeof(*report));
    report->struct_size = sizeof(*report);
    report->abi_version = SOL_METAL_ABI_VERSION;
    report->direct_mutation_batching_enabled =
        object.runtimeDirectMutationBatchingEnabled ? 1 : 0;
    report->mutation_encoder_limit = static_cast<uint32_t>(
        std::min<NSUInteger>(
            object.runtimeMutationEncoderLimit,
            std::numeric_limits<uint32_t>::max()));
    report->mutation_transient_byte_limit =
        object.runtimeMutationTransientByteLimit;
    report->batched_draw_count = object.runtimeBatchedDrawCount;
    report->draw_command_buffer_count = object.runtimeDrawCommandBufferCount;
    report->draw_render_pass_count = object.runtimeDrawRenderPassCount;
    report->borrowed_mutation_count = object.runtimeBorrowedMutationCount;
    report->borrowed_mutation_encoder_count =
        object.runtimeBorrowedMutationEncoderCount;
    report->borrowed_mutation_transient_bytes =
        object.runtimeBorrowedMutationTransientBytes;
    report->standalone_mutation_count =
        object.runtimeStandaloneMutationCount;
    report->discarded_pending_command_buffer_count =
        object.runtimeDiscardedPendingCommandBufferCount;
    report->discarded_pending_draw_count =
        object.runtimeDiscardedPendingDrawCount;
    report->maximum_draw_batch_size = static_cast<uint32_t>(
        std::min<NSUInteger>(
            object.runtimeMaximumDrawBatchSize,
            std::numeric_limits<uint32_t>::max()));
    report->maximum_mutation_count = static_cast<uint32_t>(
        std::min<NSUInteger>(
            object.runtimeMaximumMutationCount,
            std::numeric_limits<uint32_t>::max()));
    report->maximum_mutation_encoder_count = static_cast<uint32_t>(
        std::min<NSUInteger>(
            object.runtimeMaximumMutationEncoderCount,
            std::numeric_limits<uint32_t>::max()));
    report->maximum_mutation_transient_bytes =
        object.runtimeMaximumMutationTransientBytes;
    report->pending_draw_count = static_cast<uint32_t>(
        std::min<NSUInteger>(
            object.runtimeDrawCount,
            std::numeric_limits<uint32_t>::max()));
    report->pending_mutation_count = static_cast<uint32_t>(
        std::min<NSUInteger>(
            object.runtimePendingMutationCount,
            std::numeric_limits<uint32_t>::max()));
    report->pending_mutation_encoder_count = static_cast<uint32_t>(
        std::min<NSUInteger>(
            object.runtimePendingMutationEncoderCount,
            std::numeric_limits<uint32_t>::max()));
    report->pending_mutation_transient_bytes =
        object.runtimePendingMutationTransientBytes;
    for (uint32_t index = 0;
         index < SOL_METAL_RUNTIME_BATCH_FLUSH_REASON_COUNT;
         ++index) {
        report->flush_reason_counts[index] =
            object->_runtimeBatchFlushReasonCounts[index];
    }
    [object.runtimeBatchLock unlock];
    return SOL_METAL_STATUS_OK;
}

SolMetalStatus sol_metal_context_timeline_wait(
    SolMetalContextRef context,
    uint64_t value,
    uint64_t timeout_nanoseconds) {
    SolMetalContextObject *object = ContextObject(context);
    if (object == nil || value == 0) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }

    [object.timelineCondition lock];
    if (value > object.timelineSubmittedValue) {
        [object.timelineCondition unlock];
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }

    bool completed = object.timelineCompletedValue >= value;
    if (!completed && timeout_nanoseconds == 0) {
        [object.timelineCondition unlock];
        return SOL_METAL_STATUS_TIMED_OUT;
    }

    if (!completed && timeout_nanoseconds ==
        std::numeric_limits<uint64_t>::max()) {
        while (object.timelineCompletedValue < value) {
            [object.timelineCondition wait];
        }
        completed = true;
    } else if (!completed) {
        const NSTimeInterval seconds =
            static_cast<NSTimeInterval>(timeout_nanoseconds) /
            1'000'000'000.0;
        NSDate *deadline = [NSDate dateWithTimeIntervalSinceNow:seconds];
        while (object.timelineCompletedValue < value &&
               [object.timelineCondition waitUntilDate:deadline]) {
        }
        completed = object.timelineCompletedValue >= value;
    }

    const uint64_t failed = object.timelineFirstFailedValue;
    const SolMetalStatus failedStatus = object.timelineLastStatus;
    [object.timelineCondition unlock];

    if (!completed) {
        return SOL_METAL_STATUS_TIMED_OUT;
    }
    if (failed != 0 && failed <= value) {
        return failedStatus == SOL_METAL_STATUS_OK
            ? SOL_METAL_STATUS_COMMAND_FAILED
            : failedStatus;
    }
    return SOL_METAL_STATUS_OK;
}

SolMetalStatus sol_metal_context_wait_idle(
    SolMetalContextRef context,
    uint64_t timeout_nanoseconds) {
    SolMetalContextObject *object = ContextObject(context);
    if (object == nil) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }

    // Always place a marker after work that was committed before this call.
    // Waiting only for the most recently requested GAL sync can miss later
    // render or presentation command buffers during Stop/relaunch teardown.
    uint64_t idleMarker = 0;
    SolMetalStatus status = sol_metal_context_timeline_submit(
        context,
        &idleMarker);
    if (status != SOL_METAL_STATUS_OK) {
        return status;
    }
    status = sol_metal_context_timeline_wait(
        context,
        idleMarker,
        timeout_nanoseconds);
    if (status != SOL_METAL_STATUS_OK) {
        return status;
    }
    return [object runtimeCommandFailureStatus];
}

static SolMetalStatus ValidateTimelineAPI(
    SolMetalContextObject *context,
    SolMetalValidationReport *report) {
    SolMetalTimelineReport before = {};
    before.struct_size = sizeof(before);
    SolMetalStatus status = sol_metal_context_timeline_query(
        (__bridge void *)context,
        &before);
    if (status != SOL_METAL_STATUS_OK ||
        before.abi_version != SOL_METAL_ABI_VERSION ||
        before.latest_completed_value > before.latest_submitted_value) {
        SetReportError(
            report,
            SOL_METAL_STATUS_VALIDATION_FAILED,
            @"Timeline query returned an invalid initial state");
        return SOL_METAL_STATUS_VALIDATION_FAILED;
    }

    SolMetalTimelineReport undersized = {};
    undersized.struct_size = 1;
    if (sol_metal_context_timeline_query(
            (__bridge void *)context,
            &undersized) != SOL_METAL_STATUS_INCOMPATIBLE_ABI ||
        sol_metal_context_timeline_submit(
            (__bridge void *)context,
            nullptr) != SOL_METAL_STATUS_INVALID_ARGUMENT) {
        SetReportError(
            report,
            SOL_METAL_STATUS_VALIDATION_FAILED,
            @"Timeline ABI fault guards did not reject malformed input");
        return SOL_METAL_STATUS_VALIDATION_FAILED;
    }

    uint64_t values[3] = {};
    for (uint32_t index = 0; index < 3; ++index) {
        status = sol_metal_context_timeline_submit(
            (__bridge void *)context,
            &values[index]);
        if (status != SOL_METAL_STATUS_OK ||
            values[index] != before.latest_submitted_value + index + 1) {
            SetReportError(
                report,
                SOL_METAL_STATUS_VALIDATION_FAILED,
                @"Timeline submissions were not strictly monotonic");
            return SOL_METAL_STATUS_VALIDATION_FAILED;
        }
    }

    status = sol_metal_context_timeline_wait(
        (__bridge void *)context,
        values[2],
        5'000'000'000ull);
    if (status != SOL_METAL_STATUS_OK ||
        sol_metal_context_timeline_wait(
            (__bridge void *)context,
            values[2] + 1,
            0) != SOL_METAL_STATUS_INVALID_ARGUMENT) {
        SetReportError(
            report,
            SOL_METAL_STATUS_VALIDATION_FAILED,
            @"Timeline wait failed to retire ordered submissions");
        return SOL_METAL_STATUS_VALIDATION_FAILED;
    }

    SolMetalTimelineReport after = {};
    after.struct_size = sizeof(after);
    status = sol_metal_context_timeline_query(
        (__bridge void *)context,
        &after);
    if (status != SOL_METAL_STATUS_OK ||
        after.latest_submitted_value != values[2] ||
        after.latest_completed_value < values[2] ||
        after.first_failed_value != 0 ||
        after.last_status != SOL_METAL_STATUS_OK) {
        SetReportError(
            report,
            SOL_METAL_STATUS_VALIDATION_FAILED,
            @"Timeline completion report did not match the submitted work");
        return SOL_METAL_STATUS_VALIDATION_FAILED;
    }

    const uint64_t relativeValues[3] = {
        values[0] - before.latest_submitted_value,
        values[1] - before.latest_submitted_value,
        values[2] - before.latest_submitted_value,
    };
    report->command_buffers_completed += 3;
    report->bytes_verified += sizeof(relativeValues);
    report->output_signature = HashBytes(
        relativeValues,
        sizeof(relativeValues),
        report->output_signature);
    return SOL_METAL_STATUS_OK;
}

SolMetalStatus sol_metal_context_run_validation(
    SolMetalContextRef context,
    uint32_t flags,
    uint32_t iterations,
    SolMetalValidationReport *report) {
    const SolMetalStatus reportValidation = ValidateReportStruct(report);
    if (reportValidation != SOL_METAL_STATUS_OK) {
        return reportValidation;
    }

    const uint32_t unknownFlags = flags & ~SOL_METAL_VALIDATION_ALL;
    if (context == nullptr || flags == 0 || unknownFlags != 0 || iterations == 0) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }

    std::memset(report, 0, sizeof(*report));
    report->struct_size = sizeof(*report);
    report->abi_version = SOL_METAL_ABI_VERSION;
    report->requested_flags = flags;
    report->iterations_requested = iterations;
    report->output_signature = FnvOffsetBasis;
    report->last_status = SOL_METAL_STATUS_OK;

    SolMetalContextObject *object = ContextObject(context);
    if (object == nil) {
        SetReportError(
            report,
            SOL_METAL_STATUS_INVALID_ARGUMENT,
            @"SolMetal validation received a null context");
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }

    SolMetalStatus validationStatus = SOL_METAL_STATUS_OK;
    [object.validationLock lock];
    @try {
        for (uint32_t iteration = 0; iteration < iterations; ++iteration) {
            @autoreleasepool {
                struct ValidationEntry {
                    uint32_t flag;
                    ValidationFunction function;
                };
                const ValidationEntry entries[] = {
                    {SOL_METAL_VALIDATION_DEVICE, ValidateDevice},
                    {SOL_METAL_VALIDATION_BUFFER_COPY, ValidateBufferCopy},
                    {SOL_METAL_VALIDATION_TEXTURE_COPY, ValidateTextureCopy},
                    {SOL_METAL_VALIDATION_COMPUTE, ValidateCompute},
                    {SOL_METAL_VALIDATION_RENDER, ValidateRender},
                    {SOL_METAL_VALIDATION_FAULT_RECOVERY, ValidateFaultRecovery},
                    {SOL_METAL_VALIDATION_SHADER_CACHE, ValidateShaderCache},
                    {SOL_METAL_VALIDATION_SPIRV_TRANSLATION, ValidateSpirvTranslation},
                    {SOL_METAL_VALIDATION_BUFFER_API, ValidatePublicBufferAPI},
                    {SOL_METAL_VALIDATION_TEXTURE_API, ValidatePublicTextureAPI},
                    {SOL_METAL_VALIDATION_COMPUTE_PIPELINE_API,
                     ValidatePublicComputePipelineAPI},
                    {SOL_METAL_VALIDATION_RENDER_PIPELINE_API,
                     ValidatePublicRenderPipelineAPI},
                    {SOL_METAL_VALIDATION_RENDER_BINDING_API,
                     ValidatePublicRenderBindingAndFeedbackAPI},
                    {SOL_METAL_VALIDATION_RENDER_STATE_API,
                     ValidatePublicRenderStateAPI},
                    {SOL_METAL_VALIDATION_TIMELINE_API,
                     ValidateTimelineAPI},
                };

                for (const ValidationEntry &entry : entries) {
                    if ((flags & entry.flag) == 0) {
                        continue;
                    }
                    const SolMetalStatus status = RunValidationFunction(
                        entry.flag,
                        entry.function,
                        object,
                        report);
                    if (status != SOL_METAL_STATUS_OK) {
                        validationStatus = status;
                        break;
                    }
                }
                if (validationStatus != SOL_METAL_STATUS_OK) {
                    break;
                }
                report->iterations_completed += 1;
            }
        }
    } @catch (NSException *exception) {
        SetReportError(
            report,
            SOL_METAL_STATUS_INTERNAL_ERROR,
            exception.reason ?: @"Objective-C exception during SolMetal validation");
        validationStatus = SOL_METAL_STATUS_INTERNAL_ERROR;
    } @finally {
        [object.validationLock unlock];
    }
    return validationStatus;
}

SolMetalStatus sol_metal_context_present_clear(
    SolMetalContextRef context,
    void *ca_metal_layer,
    uint32_t pixel_width,
    uint32_t pixel_height,
    double red,
    double green,
    double blue,
    double alpha) {
    SolMetalContextObject *object = ContextObject(context);
    if (object == nil || ca_metal_layer == nullptr ||
        pixel_width == 0 || pixel_height == 0 ||
        !std::isfinite(red) || !std::isfinite(green) ||
        !std::isfinite(blue) || !std::isfinite(alpha) ||
        red < 0.0 || red > 1.0 || green < 0.0 || green > 1.0 ||
        blue < 0.0 || blue > 1.0 || alpha < 0.0 || alpha > 1.0) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }
    const SolMetalStatus priorRuntimeStatus = [object beginRuntimeCommand];
    if (priorRuntimeStatus != SOL_METAL_STATUS_OK) {
        return priorRuntimeStatus;
    }

    @autoreleasepool {
        bool locked = false;
        SolMetalStatus presentationStatus = SOL_METAL_STATUS_INTERNAL_ERROR;
        @try {
            CAMetalLayer *layer = (__bridge CAMetalLayer *)ca_metal_layer;
            if (![layer isKindOfClass:CAMetalLayer.class]) {
                return SOL_METAL_STATUS_INVALID_ARGUMENT;
            }
            if (layer.device == nil ||
                layer.device.registryID != object.device.registryID ||
                layer.pixelFormat != MTLPixelFormatBGRA8Unorm ||
                layer.drawableSize.width != pixel_width ||
                layer.drawableSize.height != pixel_height) {
                return SOL_METAL_STATUS_INVALID_ARGUMENT;
            }

            [object.validationLock lock];
            locked = true;

            id<CAMetalDrawable> drawable = [layer nextDrawable];
            if (drawable == nil) {
                presentationStatus = SOL_METAL_STATUS_DRAWABLE_UNAVAILABLE;
            } else {
                id<MTLCommandBuffer> commandBuffer =
                    [object.commandQueue commandBuffer];
                MTLRenderPassDescriptor *pass =
                    [MTLRenderPassDescriptor renderPassDescriptor];
                pass.colorAttachments[0].texture = drawable.texture;
                pass.colorAttachments[0].loadAction = MTLLoadActionClear;
                pass.colorAttachments[0].storeAction = MTLStoreActionStore;
                pass.colorAttachments[0].clearColor =
                    MTLClearColorMake(red, green, blue, alpha);
                id<MTLRenderCommandEncoder> encoder =
                    [commandBuffer renderCommandEncoderWithDescriptor:pass];
                if (commandBuffer == nil || encoder == nil) {
                    presentationStatus = SOL_METAL_STATUS_ALLOCATION_FAILED;
                } else {
                    [encoder endEncoding];
                    [commandBuffer presentDrawable:drawable];
                    presentationStatus = SubmitRuntimeCommandBuffer(
                        object,
                        commandBuffer,
                        @"SolMetal Clear Present");
                }
            }
        } @catch (NSException *) {
            presentationStatus = SOL_METAL_STATUS_INTERNAL_ERROR;
        } @finally {
            if (locked) {
                [object.validationLock unlock];
            }
        }
        return presentationStatus;
    }
}

SolMetalStatus sol_metal_context_present_texture(
    SolMetalContextRef context,
    void *ca_metal_layer,
    const SolMetalPresentTextureDescriptor *descriptor) {
    SolMetalContextObject *object = ContextObject(context);
    if (object == nil || descriptor == nullptr) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }
    if (descriptor->struct_size < sizeof(SolMetalPresentTextureDescriptor) ||
        descriptor->abi_version != SOL_METAL_ABI_VERSION) {
        return SOL_METAL_STATUS_INCOMPATIBLE_ABI;
    }

    SolMetalTextureObject *source = TextureObject(descriptor->source_texture);
    const bool usesLiveDrawableSize =
        descriptor->pixel_width == 0 && descriptor->pixel_height == 0;
    if (ca_metal_layer == nullptr ||
        !TextureBelongsToContext(source, object) ||
        ((descriptor->pixel_width == 0) !=
         (descriptor->pixel_height == 0)) ||
        (source.usage & SOL_METAL_TEXTURE_USAGE_SAMPLED) == 0 ||
        source.textureType != SOL_METAL_TEXTURE_TYPE_2D ||
        source.sampleCount != 1 ||
        source.texture.textureType != MTLTextureType2D ||
        source.texture.sampleCount != 1 ||
        !IsPresentationTextureFormat(source.pixelFormat) ||
        (descriptor->filter != SOL_METAL_SAMPLER_FILTER_NEAREST &&
         descriptor->filter != SOL_METAL_SAMPLER_FILTER_LINEAR)) {
        return SOL_METAL_STATUS_INVALID_ARGUMENT;
    }
    const SolMetalStatus priorRuntimeStatus = [object beginRuntimeCommand];
    if (priorRuntimeStatus != SOL_METAL_STATUS_OK) {
        return priorRuntimeStatus;
    }

    @autoreleasepool {
        bool locked = false;
        SolMetalStatus presentationStatus = SOL_METAL_STATUS_INTERNAL_ERROR;
        @try {
            CAMetalLayer *layer = (__bridge CAMetalLayer *)ca_metal_layer;
            if (![layer isKindOfClass:CAMetalLayer.class]) {
                return SOL_METAL_STATUS_INVALID_ARGUMENT;
            }
            if (layer.device == nil ||
                layer.device.registryID != object.device.registryID ||
                layer.pixelFormat != MTLPixelFormatBGRA8Unorm ||
                !std::isfinite(layer.drawableSize.width) ||
                !std::isfinite(layer.drawableSize.height) ||
                layer.drawableSize.width <= 0 ||
                layer.drawableSize.height <= 0 ||
                (!usesLiveDrawableSize &&
                 (layer.drawableSize.width != descriptor->pixel_width ||
                  layer.drawableSize.height != descriptor->pixel_height))) {
                return SOL_METAL_STATUS_INVALID_ARGUMENT;
            }

            [object.validationLock lock];
            locked = true;

            NSError *resourceError = nil;
            if (![object preparePresentationResources:&resourceError]) {
                presentationStatus = resourceError.code ==
                        SOL_METAL_STATUS_ALLOCATION_FAILED
                    ? SOL_METAL_STATUS_ALLOCATION_FAILED
                    : SOL_METAL_STATUS_SHADER_COMPILATION_FAILED;
            } else {
                id<CAMetalDrawable> drawable = [layer nextDrawable];
                if (drawable == nil) {
                    presentationStatus = SOL_METAL_STATUS_DRAWABLE_UNAVAILABLE;
                } else {
                    id<MTLCommandBuffer> commandBuffer =
                        [object.commandQueue commandBuffer];
                    if (commandBuffer == nil) {
                        presentationStatus = SOL_METAL_STATUS_ALLOCATION_FAILED;
                    } else {
                        presentationStatus = [object
                            encodePresentationTexture:source.texture
                            destinationTexture:drawable.texture
                            commandBuffer:commandBuffer
                            descriptor:*descriptor
                            loadAction:MTLLoadActionClear];
                        if (presentationStatus == SOL_METAL_STATUS_OK) {
                            [commandBuffer presentDrawable:drawable];
                            presentationStatus = SubmitRuntimeCommandBuffer(
                                object,
                                commandBuffer,
                                @"SolMetal Texture Present");
                        }
                    }
                }
            }
        } @catch (NSException *) {
            presentationStatus = SOL_METAL_STATUS_INTERNAL_ERROR;
        } @finally {
            if (locked) {
                [object.validationLock unlock];
            }
        }
        return presentationStatus;
    }
}
